150	    public long getFlags() {
151	        return flags;
152	    }
153	
154	    public boolean hasFlag(final int flag) {
155	        return (flags & Integer.toUnsignedLong(flag)) != 0;
156	    }
157	
158	    public boolean hasFlag(final long flag) {
159	        return (flags & flag) != 0;
160	    }
161	
162	    public boolean notHasFlag(final int flag) {
163	        return !hasFlag(flag);
164	    }
165	
166	    public boolean notHasFlag(final long flag) {
167	        return !hasFlag(flag);
168	    }
