8186	    /**
8187	     * There are three ways to call this:
8188	     *  - no service specified: dump all the services
8189	     *  - a flattened component name that matched an existing service was specified as the
8190	     *    first arg: dump that one service
8191	     *  - the first arg isn't the flattened component name of an existing service:
8192	     *    dump all services whose component contains the first arg as a substring
8193	     */
8194	    protected boolean dumpService(FileDescriptor fd, PrintWriter pw, String name, int[] users,
8195	            String[] args, int opti, boolean dumpAll) {
8196	        try {
8197	            mAm.mOomAdjuster.mCachedAppOptimizer.enableFreezer(false);
8198	            final ArrayList<ServiceRecord> services = new ArrayList<>();
8199	
8200	            final Predicate<ServiceRecord> filter = DumpUtils.filterRecord(name);
8201	
8202	            synchronized (mAm) {
8203	                if (users == null) {
8204	                    users = mAm.mUserController.getUsers();
8205	                }
8206	
8207	                for (int user : users) {
8208	                    ServiceMap smap = mServiceMap.get(user);
8209	                    if (smap == null) {
8210	                        continue;
8211	                    }
8212	                    ArrayMap<ComponentName, ServiceRecord> alls = smap.mServicesByInstanceName;
8213	                    for (int i=0; i<alls.size(); i++) {
8214	                        ServiceRecord r1 = alls.valueAt(i);
8215	
8216	                        if (filter.test(r1)) {
8217	                            services.add(r1);
8218	                        }
8219	                    }
8220	                }
8221	            }
8222	
8223	            if (services.size() <= 0) {
8224	                return false;
8225	            }
8226	
8227	            // Sort by component name.
8228	            services.sort(Comparator.comparing(WithComponentName::getComponentName));
8229	
8230	            boolean needSep = false;
8231	            for (int i=0; i<services.size(); i++) {
8232	                if (needSep) {
8233	                    pw.println();
8234	                }
8235	                needSep = true;
8236	                dumpService("", fd, pw, services.get(i), args, dumpAll);
8237	            }
8238	            return true;
8239	        } finally {
8240	            mAm.mOomAdjuster.mCachedAppOptimizer.enableFreezer(true);
8241	        }
8242	    }
