8244	    /**
8245	     * Invokes IApplicationThread.dumpService() on the thread of the specified service if
8246	     * there is a thread associated with the service.
8247	     */
8248	    private void dumpService(String prefix, FileDescriptor fd, PrintWriter pw,
8249	            final ServiceRecord r, String[] args, boolean dumpAll) {
8250	        String innerPrefix = prefix + "  ";
8251	        synchronized (mAm) {
8252	            pw.print(prefix); pw.print("SERVICE ");
8253	            pw.print(r.shortInstanceName); pw.print(" ");
8254	            pw.print(Integer.toHexString(System.identityHashCode(r)));
8255	            pw.print(" pid=");
8256	            if (r.app != null) {
8257	                pw.print(r.app.getPid());
8258	                pw.print(" user="); pw.println(r.userId);
8259	            } else pw.println("(not running)");
8260	            if (dumpAll) {
8261	                r.dump(pw, innerPrefix);
8262	            }
8263	        }
8264	        IApplicationThread thread;
8265	        if (r.app != null && (thread = r.app.getThread()) != null) {
8266	            pw.print(prefix); pw.println("  Client:");
8267	            pw.flush();
8268	            try {
8269	                TransferPipe tp = new TransferPipe();
8270	                try {
8271	                    thread.dumpService(tp.getWriteFd(), r, args);
8272	                    tp.setBufferPrefix(prefix + "    ");
8273	                    tp.go(fd);
8274	                } finally {
8275	                    tp.kill();
8276	                }
8277	            } catch (IOException e) {
8278	                pw.println(prefix + "    Failure while dumping the service: " + e);
8279	            } catch (RemoteException e) {
8280	                pw.println(prefix + "    Got a RemoteException while dumping the service");
8281	            }
8282	        }
8283	    }
