8292	    /**
8293	     * There are two FGS restrictions:
8294	     * In R, mAllowWhileInUsePermissionInFgs is to allow while-in-use permissions in foreground
8295	     *  service or not. while-in-use permissions in FGS started from background might be restricted.
8296	     * In S, mAllowStartForeground is to allow FGS to startForeground or not. Service started
8297	     * from background may not become a FGS.
8298	     * @param callingPackage caller app's package name.
8299	     * @param callingUid caller app's uid.
8300	     * @param intent intent to start/bind service.
8301	     * @param r the service to start.
8302	     * @param inBindService True if it's called from bindService().
8303	     * @param forBoundFgs set to true if it's called from Service.startForeground() for a
8304	     *                    service that's not started but bound.
8305	     */
8306	    private void setFgsRestrictionLocked(String callingPackage,
8307	            int callingPid, int callingUid, Intent intent, ServiceRecord r, int userId,
8308	            BackgroundStartPrivileges backgroundStartPrivileges, boolean inBindService,
8309	            boolean forBoundFgs) {
8310	
8311	        @ReasonCode int allowWiu;
8312	        @ReasonCode int allowStart;
8313	
8314	        // If called from bindService(), do not update the actual fields, but instead
8315	        // keep it in a separate set of fields.
8316	        if (inBindService) {
8317	            allowWiu = r.mAllowWiu_inBindService;
8318	            allowStart = r.mAllowStart_inBindService;
8319	        } else {
8320	            allowWiu = r.mAllowWiu_noBinding;
8321	            allowStart = r.mAllowStart_noBinding;
8322	        }
8323	
8324	        if ((allowWiu == REASON_DENIED) || (allowStart == REASON_DENIED)) {
8325	            @ReasonCode final int allowWhileInUse = shouldAllowFgsWhileInUsePermissionLocked(
8326	                    callingPackage, callingPid, callingUid, r.app, backgroundStartPrivileges);
8327	            if (allowWiu == REASON_DENIED) {
8328	                allowWiu = allowWhileInUse;
8329	            }
8330	            if (allowStart == REASON_DENIED) {
8331	                allowStart = shouldAllowFgsStartForegroundWithBindingCheckLocked(
8332	                        allowWhileInUse, callingPackage, callingPid, callingUid, intent, r,
8333	                        backgroundStartPrivileges, inBindService);
8334	            }
8335	        }
8336	
8337	        if (inBindService) {
8338	            r.mAllowWiu_inBindService = allowWiu;
8339	            r.mAllowStart_inBindService = allowStart;
8340	        } else {
8341	            if (!forBoundFgs) {
8342	                // This is for "normal" situation -- either:
8343	                // - in Context.start[Foreground]Service()
8344	                // - or, in Service.startForeground() on a started service.
8345	                r.mAllowWiu_noBinding = allowWiu;
8346	                r.mAllowStart_noBinding = allowStart;
8347	            } else {
8348	                // Service.startForeground() is called on a service that's not started, but bound.
8349	                // In this case, we set them to "byBindings", not "noBinding", because
8350	                // we don't want to use them when we calculate the "legacy" code.
8351	                //
8352	                // We don't want to set them to "no binding" codes, because on U-QPR1 and below,
8353	                // we didn't call setFgsRestrictionLocked() in the code path which sets
8354	                // forBoundFgs to true, and we wanted to preserve the original behavior in other
8355	                // places to compare the legacy and new logic.
8356	                if (r.mAllowWiu_byBindings == REASON_DENIED) {
8357	                    r.mAllowWiu_byBindings = allowWiu;
8358	                }
8359	                if (r.mAllowStart_byBindings == REASON_DENIED) {
8360	                    r.mAllowStart_byBindings = allowStart;
8361	                }
8362	            }
8363	            // Also do a binding client check, unless called from bindService().
8364	            if (r.mAllowWiu_byBindings == REASON_DENIED) {
8365	                r.mAllowWiu_byBindings =
8366	                        shouldAllowFgsWhileInUsePermissionByBindingsLocked(callingUid);
8367	            }
8368	            if (r.mAllowStart_byBindings == REASON_DENIED) {
8369	                r.mAllowStart_byBindings = r.mAllowWiu_byBindings;
8370	            }
8371	        }
8372	    }
