8406	    /**
8407	     * Should allow while-in-use permissions in FGS or not.
8408	     * A typical BG started FGS is not allowed to have while-in-use permissions.
8409	     *
8410	     * @param callingPackage caller app's package name.
8411	     * @param callingUid     caller app's uid.
8412	     * @param targetProcess  the process of the service to start.
8413	     * @return {@link ReasonCode}
8414	     */
8415	    @ReasonCode int shouldAllowFgsWhileInUsePermissionLocked(String callingPackage,
8416	            int callingPid, int callingUid, @Nullable ProcessRecord targetProcess,
8417	            BackgroundStartPrivileges backgroundStartPrivileges) {
8418	        int ret = REASON_DENIED;
8419	
8420	        final int uidState = mAm.getUidStateLocked(callingUid);
8421	        if (ret == REASON_DENIED) {
8422	            // Allow FGS while-in-use if the caller's process state is PROCESS_STATE_PERSISTENT,
8423	            // PROCESS_STATE_PERSISTENT_UI or PROCESS_STATE_TOP.
8424	            if (uidState <= PROCESS_STATE_TOP) {
8425	                ret = getReasonCodeFromProcState(uidState);
8426	            }
8427	        }
8428	
8429	        if (ret == REASON_DENIED) {
8430	            // Allow FGS while-in-use if the caller has visible activity.
8431	            // Here we directly check ActivityTaskManagerService, instead of checking
8432	            // PendingStartActivityUids in ActivityManagerService, which gives the same result.
8433	            final boolean isCallingUidVisible = mAm.mAtmInternal.isUidForeground(callingUid);
8434	            if (isCallingUidVisible) {
8435	                ret = REASON_UID_VISIBLE;
8436	            }
8437	        }
8438	
8439	        if (ret == REASON_DENIED) {
8440	            // Allow FGS while-in-use if the background activity start flag is on. Because
8441	            // activity start can lead to FGS start in TOP state and obtain while-in-use.
8442	            if (backgroundStartPrivileges.allowsBackgroundActivityStarts()) {
8443	                ret = REASON_START_ACTIVITY_FLAG;
8444	            }
8445	        }
8446	
8447	        if (ret == REASON_DENIED) {
8448	            boolean isCallerSystem = false;
8449	            final int callingAppId = UserHandle.getAppId(callingUid);
8450	            // Allow FGS while-in-use for a list of special UIDs.
8451	            switch (callingAppId) {
8452	                case ROOT_UID:
8453	                case SYSTEM_UID:
8454	                case NFC_UID:
8455	                case SHELL_UID:
8456	                    isCallerSystem = true;
8457	                    break;
8458	                default:
8459	                    isCallerSystem = false;
8460	                    break;
8461	            }
8462	
8463	            if (isCallerSystem) {
8464	                ret = REASON_SYSTEM_UID;
8465	            }
8466	        }
8467	
8468	        if (ret == REASON_DENIED) {
8469	            // Allow FGS while-in-use if the WindowManager allows background activity start.
8470	            // This is mainly to get the 10 seconds grace period if any activity in the caller has
8471	            // either started or finished very recently. The binding flag
8472	            // BIND_ALLOW_BACKGROUND_ACTIVITY_STARTS is also allowed by the check here.
8473	            final Integer allowedType = mAm.mProcessList.searchEachLruProcessesLOSP(false, pr -> {
8474	                if (pr.uid == callingUid) {
8475	                    if (pr.getWindowProcessController().areBackgroundFgsStartsAllowed()) {
8476	                        return REASON_ACTIVITY_STARTER;
8477	                    }
8478	                }
8479	                return null;
8480	            });
8481	            if (allowedType != null) {
8482	                ret = allowedType;
8483	            }
8484	        }
8485	
8486	        if (ret == REASON_DENIED) {
8487	            // Allow FGS while-in-use if the caller UID is in ActivityManagerService's
8488	            // mFgsWhileInUseTempAllowList. This is a temp allowlist to allow FGS while-in-use. It
8489	            // is used when MediaSessionService's bluetooth button or play/resume/stop commands are
8490	            // issued. The typical temp allowlist duration is 10 seconds.
8491	            // This temp allowlist mechanism can also be called by other system_server internal
8492	            // components such as Telephone/VOIP if they want to start a FGS and get while-in-use.
8493	            if (mAm.mInternal.isTempAllowlistedForFgsWhileInUse(callingUid)) {
8494	                return REASON_TEMP_ALLOWED_WHILE_IN_USE;
8495	            }
8496	        }
8497	
8498	        if (ret == REASON_DENIED) {
8499	            if (targetProcess != null) {
8500	                // Allow FGS while-in-use if the caller of the instrumentation has
8501	                // START_ACTIVITIES_FROM_BACKGROUND permission.
8502	                ActiveInstrumentation instr = targetProcess.getActiveInstrumentation();
8503	                if (instr != null && instr.mHasBackgroundActivityStartsPermission) {
8504	                    ret = REASON_INSTR_BACKGROUND_ACTIVITY_PERMISSION;
8505	                }
8506	            }
8507	        }
8508	
8509	        if (ret == REASON_DENIED) {
8510	            // Allow FGS while-in-use if the caller has START_ACTIVITIES_FROM_BACKGROUND
8511	            // permission, because starting an activity can lead to starting FGS from the TOP state
8512	            // and obtain while-in-use.
8513	            if (mAm.checkPermission(START_ACTIVITIES_FROM_BACKGROUND, callingPid, callingUid)
8514	                    == PERMISSION_GRANTED) {
8515	                ret = REASON_BACKGROUND_ACTIVITY_PERMISSION;
8516	            }
8517	        }
8518	
8519	        if (ret == REASON_DENIED) {
8520	            // Allow FGS while-in-use if the caller is in the while-in-use allowlist. Right now
8521	            // AttentionService and SystemCaptionsService packageName are in this allowlist.
8522	            if (verifyPackage(callingPackage, callingUid)) {
8523	                final boolean isAllowedPackage =
8524	                        mAllowListWhileInUsePermissionInFgs.contains(callingPackage);
8525	                if (isAllowedPackage) {
8526	                    ret = REASON_ALLOWLISTED_PACKAGE;
8527	                }
8528	            } else {
8529	                EventLog.writeEvent(0x534e4554, "215003903", callingUid,
8530	                        "callingPackage:" + callingPackage + " does not belong to callingUid:"
8531	                                + callingUid);
8532	            }
8533	        }
8534	
8535	        if (ret == REASON_DENIED) {
8536	            // Allow FGS while-in-use if the caller is the device owner.
8537	            final boolean isDeviceOwner = mAm.mInternal.isDeviceOwner(callingUid);
8538	            if (isDeviceOwner) {
8539	                ret = REASON_DEVICE_OWNER;
8540	            }
8541	        }
8542	        return ret;
8543	    }
