8545	    /**
8546	     * Check all bindings into the calling UID, and see if:
8547	     * - It's bound by a TOP app
8548	     * - or, bound by a persistent process with BIND_ALLOW_BACKGROUND_ACTIVITY_STARTS.
8549	     */
8550	    private @ReasonCode int shouldAllowFgsWhileInUsePermissionByBindingsLocked(int callingUid) {
8551	        final ArraySet<Integer> checkedClientUids = new ArraySet<>();
8552	        final Integer result = mAm.mProcessList.searchEachLruProcessesLOSP(
8553	                false, pr -> {
8554	                    if (pr.uid != callingUid) {
8555	                        return null;
8556	                    }
8557	                    final ProcessServiceRecord psr = pr.mServices;
8558	                    final int serviceCount = psr.mServices.size();
8559	                    for (int svc = 0; svc < serviceCount; svc++) {
8560	                        final ArrayMap<IBinder, ArrayList<ConnectionRecord>> conns =
8561	                                psr.mServices.valueAt(svc).getConnections();
8562	                        final int size = conns.size();
8563	                        for (int conni = 0; conni < size; conni++) {
8564	                            final ArrayList<ConnectionRecord> crs = conns.valueAt(conni);
8565	                            for (int con = 0; con < crs.size(); con++) {
8566	                                final ConnectionRecord cr = crs.get(con);
8567	                                final ProcessRecord clientPr = cr.binding.client;
8568	                                final int clientUid = clientPr.uid;
8569	
8570	                                // An UID can bind to itself, do not check on itself again.
8571	                                // Also skip already checked clientUid.
8572	                                if (clientUid == callingUid
8573	                                        || checkedClientUids.contains(clientUid)) {
8574	                                    continue;
8575	                                }
8576	
8577	                                // Binding found, check the client procstate and the flag.
8578	                                final int clientUidState = mAm.getUidStateLocked(callingUid);
8579	                                final boolean boundByTop = clientUidState == PROCESS_STATE_TOP;
8580	                                final boolean boundByPersistentWithBal =
8581	                                        clientUidState < PROCESS_STATE_TOP
8582	                                        && cr.hasFlag(
8583	                                                Context.BIND_ALLOW_BACKGROUND_ACTIVITY_STARTS);
8584	                                if (boundByTop || boundByPersistentWithBal) {
8585	                                    return getReasonCodeFromProcState(clientUidState);
8586	                                }
8587	
8588	                                // Don't check the same UID.
8589	                                checkedClientUids.add(clientUid);
8590	                            }
8591	                        }
8592	                    }
8593	                    return null;
8594	                });
8595	        return result == null ? REASON_DENIED : result;
8596	    }
