8598	    /**
8599	     * The uid is not allowed to start FGS, but the uid has a service that is bound
8600	     * by a clientUid, if the clientUid can start FGS, then the clientUid can propagate its
8601	     * BG-FGS-start capability down to the callingUid.
8602	     * @param uid
8603	     * @return The first binding client's packageName that can start FGS. Return null if no client
8604	     *         can start FGS.
8605	     */
8606	    private String canBindingClientStartFgsLocked(int uid) {
8607	        String bindFromPackage = null;
8608	        final ArraySet<Integer> checkedClientUids = new ArraySet<>();
8609	        final Pair<Integer, String> isAllowed = mAm.mProcessList.searchEachLruProcessesLOSP(
8610	                false, pr -> {
8611	                if (pr.uid == uid) {
8612	                    final ProcessServiceRecord psr = pr.mServices;
8613	                    final int serviceCount = psr.mServices.size();
8614	                    for (int svc = 0; svc < serviceCount; svc++) {
8615	                        final ArrayMap<IBinder, ArrayList<ConnectionRecord>> conns =
8616	                                psr.mServices.valueAt(svc).getConnections();
8617	                        final int size = conns.size();
8618	                        for (int conni = 0; conni < size; conni++) {
8619	                            final ArrayList<ConnectionRecord> crs = conns.valueAt(conni);
8620	                            for (int con = 0; con < crs.size(); con++) {
8621	                                final ConnectionRecord cr = crs.get(con);
8622	                                final ProcessRecord clientPr = cr.binding.client;
8623	                                // If a binding is from a persistent process, we don't automatically
8624	                                // always allow the bindee to allow FGS BG starts. In this case,
8625	                                // the binder will have to explicitly make sure the bindee's
8626	                                // procstate will be BFGS or above. Otherwise, for example, even if
8627	                                // the system server binds to an app with BIND_NOT_FOREGROUND,
8628	                                // the binder would have to be able to start FGS, which is not what
8629	                                // we want. (e.g. job services shouldn't be allowed BG-FGS.)
8630	                                if (clientPr.isPersistent()) {
8631	                                    continue;
8632	                                }
8633	                                final int clientPid = clientPr.mPid;
8634	                                final int clientUid = clientPr.uid;
8635	                                // An UID can bind to itself, do not check on itself again.
8636	                                // Also skip already checked clientUid.
8637	                                if (clientUid == uid
8638	                                        || checkedClientUids.contains(clientUid)) {
8639	                                    continue;
8640	                                }
8641	                                final String clientPackageName = cr.clientPackageName;
8642	                                final @ReasonCode int allowWhileInUse2 =
8643	                                        shouldAllowFgsWhileInUsePermissionLocked(
8644	                                                clientPackageName,
8645	                                                clientPid, clientUid, null /* targetProcess */,
8646	                                                BackgroundStartPrivileges.NONE);
8647	                                final @ReasonCode int allowStartFgs =
8648	                                        shouldAllowFgsStartForegroundNoBindingCheckLocked(
8649	                                                allowWhileInUse2,
8650	                                                clientPid, clientUid, clientPackageName,
8651	                                                null /* targetService */,
8652	                                                BackgroundStartPrivileges.NONE);
8653	                                if (allowStartFgs != REASON_DENIED) {
8654	                                    return new Pair<>(allowStartFgs, clientPackageName);
8655	                                } else {
8656	                                    checkedClientUids.add(clientUid);
8657	                                }
8658	
8659	                            }
8660	                        }
8661	                    }
8662	                }
8663	                return null;
8664	            });
8665	        if (isAllowed != null) {
8666	            bindFromPackage = isAllowed.second;
8667	        }
8668	        return bindFromPackage;
8669	    }
