8671	    /**
8672	     * Should allow the FGS to start (AKA startForeground()) or not.
8673	     * The check in this method is in addition to check in
8674	     * {@link #shouldAllowFgsWhileInUsePermissionLocked}
8675	     * @param allowWhileInUse the return code from {@link #shouldAllowFgsWhileInUsePermissionLocked}
8676	     * @param callingPackage caller app's package name.
8677	     * @param callingUid caller app's uid.
8678	     * @param intent intent to start/bind service.
8679	     * @param r the service to start.
8680	     * @return {@link ReasonCode}
8681	     */
8682	    private @ReasonCode int shouldAllowFgsStartForegroundWithBindingCheckLocked(
8683	            @ReasonCode int allowWhileInUse, String callingPackage, int callingPid,
8684	            int callingUid, Intent intent, ServiceRecord r,
8685	            BackgroundStartPrivileges backgroundStartPrivileges, boolean isBindService) {
8686	        ActivityManagerService.FgsTempAllowListItem tempAllowListReason =
8687	                r.mInfoTempFgsAllowListReason = mAm.isAllowlistedForFgsStartLOSP(callingUid);
8688	        int ret = shouldAllowFgsStartForegroundNoBindingCheckLocked(allowWhileInUse, callingPid,
8689	                callingUid, callingPackage, r, backgroundStartPrivileges);
8690	
8691	        // If an app (App 1) is bound by another app (App 2) that could start an FGS, then App 1
8692	        // is also allowed to start an FGS. We check all the binding
8693	        // in canBindingClientStartFgsLocked() to do this check.
8694	        // (Note we won't check more than 1 level of binding.)
8695	        // [bookmark: 61867f60-007c-408c-a2c4-e19e96056135] -- this code is referred to from
8696	        // OomAdjuster.
8697	        String bindFromPackage = null;
8698	        if (ret == REASON_DENIED) {
8699	            bindFromPackage = canBindingClientStartFgsLocked(callingUid);
8700	            if (bindFromPackage != null) {
8701	                ret = REASON_FGS_BINDING;
8702	            }
8703	        }
8704	
8705	        final int uidState = mAm.getUidStateLocked(callingUid);
8706	        int callerTargetSdkVersion = -1;
8707	        try {
8708	            callerTargetSdkVersion = mAm.mContext.getPackageManager()
8709	                    .getTargetSdkVersion(callingPackage);
8710	        } catch (PackageManager.NameNotFoundException ignored) {
8711	        }
8712	        final boolean uidBfsl = (mAm.getUidProcessCapabilityLocked(callingUid)
8713	                & PROCESS_CAPABILITY_BFSL) != 0;
8714	        final String debugInfo =
8715	                "[callingPackage: " + callingPackage
8716	                        + "; callingUid: " + callingUid
8717	                        + "; uidState: " + ProcessList.makeProcStateString(uidState)
8718	                        + "; uidBFSL: " + (uidBfsl ? "[BFSL]" : "n/a")
8719	                        + "; intent: " + intent
8720	                        + "; code:" + reasonCodeToString(ret)
8721	                        + "; tempAllowListReason:<"
8722	                        + (tempAllowListReason == null ? null :
8723	                                (tempAllowListReason.mReason
8724	                                        + ",reasonCode:"
8725	                                        + reasonCodeToString(tempAllowListReason.mReasonCode)
8726	                                        + ",duration:" + tempAllowListReason.mDuration
8727	                                        + ",callingUid:" + tempAllowListReason.mCallingUid))
8728	                        + ">"
8729	                        + "; allowWiu:" + allowWhileInUse
8730	                        + "; targetSdkVersion:" + r.appInfo.targetSdkVersion
8731	                        + "; callerTargetSdkVersion:" + callerTargetSdkVersion
8732	                        + "; startForegroundCount:" + r.mStartForegroundCount
8733	                        + "; bindFromPackage:" + bindFromPackage
8734	                        + ": isBindService:" + isBindService
8735	                        + "]";
8736	        if (!debugInfo.equals(r.mInfoAllowStartForeground)) {
8737	            r.mLoggedInfoAllowStartForeground = false;
8738	            r.mInfoAllowStartForeground = debugInfo;
8739	        }
8740	        return ret;
8741	    }
