8743	    private @ReasonCode int shouldAllowFgsStartForegroundNoBindingCheckLocked(
8744	            @ReasonCode int allowWhileInUse, int callingPid, int callingUid, String callingPackage,
8745	            @Nullable ServiceRecord targetService,
8746	            BackgroundStartPrivileges backgroundStartPrivileges) {
8747	        int ret = allowWhileInUse;
8748	
8749	        if (ret == REASON_DENIED) {
8750	            final int uidState = mAm.getUidStateLocked(callingUid);
8751	            // Is the calling UID at PROCESS_STATE_TOP or above?
8752	            if (uidState <= PROCESS_STATE_TOP) {
8753	                ret = getReasonCodeFromProcState(uidState);
8754	            }
8755	        }
8756	
8757	        if (ret == REASON_DENIED) {
8758	            final boolean uidBfsl =
8759	                    (mAm.getUidProcessCapabilityLocked(callingUid) & PROCESS_CAPABILITY_BFSL) != 0;
8760	            final Integer allowedType = mAm.mProcessList.searchEachLruProcessesLOSP(false, app -> {
8761	                if (app.uid == callingUid) {
8762	                    final ProcessStateRecord state = app.mState;
8763	                    final int procstate = state.getCurProcState();
8764	                    if ((procstate <= PROCESS_STATE_BOUND_TOP)
8765	                            || (uidBfsl && (procstate <= PROCESS_STATE_BOUND_FOREGROUND_SERVICE))) {
8766	                        return getReasonCodeFromProcState(procstate);
8767	                    } else {
8768	                        final ActiveInstrumentation instr = app.getActiveInstrumentation();
8769	                        if (instr != null
8770	                                && instr.mHasBackgroundForegroundServiceStartsPermission) {
8771	                            return REASON_INSTR_BACKGROUND_FGS_PERMISSION;
8772	                        }
8773	                        final long lastInvisibleTime = app.mState.getLastInvisibleTime();
8774	                        if (lastInvisibleTime > 0 && lastInvisibleTime < Long.MAX_VALUE) {
8775	                            final long sinceLastInvisible = SystemClock.elapsedRealtime()
8776	                                    - lastInvisibleTime;
8777	                            if (sinceLastInvisible < mAm.mConstants.mFgToBgFgsGraceDuration) {
8778	                                return REASON_ACTIVITY_VISIBILITY_GRACE_PERIOD;
8779	                            }
8780	                        }
8781	                    }
8782	                }
8783	                return null;
8784	            });
8785	            if (allowedType != null) {
8786	                ret = allowedType;
8787	            }
8788	        }
8789	
8790	        if (ret == REASON_DENIED) {
8791	            if (mAm.checkPermission(START_FOREGROUND_SERVICES_FROM_BACKGROUND, callingPid,
8792	                    callingUid) == PERMISSION_GRANTED) {
8793	                ret = REASON_BACKGROUND_FGS_PERMISSION;
8794	            }
8795	        }
8796	
8797	        if (ret == REASON_DENIED) {
8798	            if (backgroundStartPrivileges.allowsBackgroundFgsStarts()) {
8799	                ret = REASON_START_ACTIVITY_FLAG;
8800	            }
8801	        }
8802	
8803	        if (ret == REASON_DENIED) {
8804	            if (mAm.mAtmInternal.hasSystemAlertWindowPermission(
8805	                                    callingUid, callingPid, callingPackage)) {
8806	                // Starting from Android V, it is not enough to only have the SYSTEM_ALERT_WINDOW
8807	                // permission granted - apps must also be showing an overlay window.
8808	                if (Flags.fgsDisableSaw()
8809	                        && CompatChanges.isChangeEnabled(FGS_SAW_RESTRICTIONS, callingUid)) {
8810	                    final UidRecord uidRecord = mAm.mProcessList.getUidRecordLOSP(callingUid);
8811	                    if (uidRecord != null) {
8812	                        for (int i = uidRecord.getNumOfProcs() - 1; i >= 0; i--) {
8813	                            final ProcessRecord pr = uidRecord.getProcessRecordByIndex(i);
8814	                            if (pr != null && pr.mState.hasOverlayUi()) {
8815	                                ret = REASON_SYSTEM_ALERT_WINDOW_PERMISSION;
8816	                                break;
8817	                            }
8818	                        }
8819	                    }
8820	                } else { // pre-V logic
8821	                    ret = REASON_SYSTEM_ALERT_WINDOW_PERMISSION;
8822	                }
8823	            }
8824	        }
8825	
8826	        // Check for CDM apps with either REQUEST_COMPANION_RUN_IN_BACKGROUND or
8827	        // REQUEST_COMPANION_START_FOREGROUND_SERVICES_FROM_BACKGROUND.
8828	        // Note: When a CDM app has REQUEST_COMPANION_RUN_IN_BACKGROUND, the app is also put
8829	        // in the user-allowlist. However, in this case, we want to use the reason code
8830	        // REASON_COMPANION_DEVICE_MANAGER, so this check needs to be before the
8831	        // isAllowlistedForFgsStartLOSP check.
8832	        if (ret == REASON_DENIED) {
8833	            final boolean isCompanionApp = mAm.mInternal.isAssociatedCompanionApp(
8834	                    UserHandle.getUserId(callingUid), callingUid);
8835	            if (isCompanionApp) {
8836	                if (isPermissionGranted(
8837	                        REQUEST_COMPANION_START_FOREGROUND_SERVICES_FROM_BACKGROUND,
8838	                        callingPid, callingUid)
8839	                        || isPermissionGranted(REQUEST_COMPANION_RUN_IN_BACKGROUND,
8840	                        callingPid, callingUid)) {
8841	                    ret = REASON_COMPANION_DEVICE_MANAGER;
8842	                }
8843	            }
8844	        }
8845	
8846	        if (ret == REASON_DENIED) {
8847	            ActivityManagerService.FgsTempAllowListItem item =
8848	                    mAm.isAllowlistedForFgsStartLOSP(callingUid);
8849	            if (item != null) {
8850	                if (item == ActivityManagerService.FAKE_TEMP_ALLOW_LIST_ITEM) {
8851	                    ret = REASON_SYSTEM_ALLOW_LISTED;
8852	                } else {
8853	                    ret = item.mReasonCode;
8854	                }
8855	            }
8856	        }
8857	
8858	        if (ret == REASON_DENIED) {
8859	            if (UserManager.isDeviceInDemoMode(mAm.mContext)) {
8860	                ret = REASON_DEVICE_DEMO_MODE;
8861	            }
8862	        }
8863	
8864	        if (ret == REASON_DENIED) {
8865	            // Is the calling UID a profile owner app?
8866	            final boolean isProfileOwner = mAm.mInternal.isProfileOwner(callingUid);
8867	            if (isProfileOwner) {
8868	                ret = REASON_PROFILE_OWNER;
8869	            }
8870	        }
8871	
8872	        if (ret == REASON_DENIED) {
8873	            final AppOpsManager appOpsManager = mAm.getAppOpsManager();
8874	            if (mAm.mConstants.mFlagSystemExemptPowerRestrictionsEnabled
8875	                    && appOpsManager.checkOpNoThrow(
8876	                    AppOpsManager.OP_SYSTEM_EXEMPT_FROM_POWER_RESTRICTIONS, callingUid,
8877	                    callingPackage) == AppOpsManager.MODE_ALLOWED) {
8878	                ret = REASON_SYSTEM_EXEMPT_APP_OP;
8879	            }
8880	        }
8881	
8882	        if (ret == REASON_DENIED) {
8883	            final AppOpsManager appOpsManager = mAm.getAppOpsManager();
8884	            if (appOpsManager.checkOpNoThrow(AppOpsManager.OP_ACTIVATE_VPN, callingUid,
8885	                    callingPackage) == AppOpsManager.MODE_ALLOWED) {
8886	                ret = REASON_OP_ACTIVATE_VPN;
8887	            } else if (appOpsManager.checkOpNoThrow(AppOpsManager.OP_ACTIVATE_PLATFORM_VPN,
8888	                    callingUid, callingPackage) == AppOpsManager.MODE_ALLOWED) {
8889	                ret = REASON_OP_ACTIVATE_PLATFORM_VPN;
8890	            }
8891	        }
8892	
8893	        if (ret == REASON_DENIED) {
8894	            final String inputMethod =
8895	                    Settings.Secure.getStringForUser(mAm.mContext.getContentResolver(),
8896	                            Settings.Secure.DEFAULT_INPUT_METHOD,
8897	                            UserHandle.getUserId(callingUid));
8898	            if (inputMethod != null) {
8899	                final ComponentName cn = ComponentName.unflattenFromString(inputMethod);
8900	                if (cn != null && cn.getPackageName().equals(callingPackage)) {
8901	                    ret = REASON_CURRENT_INPUT_METHOD;
8902	                }
8903	            }
8904	        }
8905	
8906	        if (ret == REASON_DENIED) {
8907	            if (mAm.mConstants.mFgsAllowOptOut
8908	                    && targetService != null
8909	                    && targetService.appInfo.hasRequestForegroundServiceExemption()) {
8910	                ret = REASON_OPT_OUT_REQUESTED;
8911	            }
8912	        }
8913	
8914	        return ret;
8915	    }
