8954	    private boolean isBgFgsRestrictionEnabled(ServiceRecord r, int actualCallingUid) {
8955	        // mFlagFgsStartRestrictionEnabled controls whether to enable the BG FGS restrictions:
8956	        // - If true (default), BG-FGS restrictions are enabled if the service targets >= S.
8957	        // - If false, BG-FGS restrictions are disabled for all apps.
8958	        if (!mAm.mConstants.mFlagFgsStartRestrictionEnabled) {
8959	            return false;
8960	        }
8961	
8962	        // If the service target below S, then don't enable the restrictions.
8963	        if (!CompatChanges.isChangeEnabled(FGS_BG_START_RESTRICTION_CHANGE_ID, r.appInfo.uid)) {
8964	            return false;
8965	        }
8966	
8967	        // mFgsStartRestrictionCheckCallerTargetSdk controls whether we take the caller's target
8968	        // SDK level into account or not:
8969	        // - If true (default), BG-FGS restrictions only happens if the caller _also_ targets >= S.
8970	        // - If false, BG-FGS restrictions do _not_ use the caller SDK levels.
8971	        if (!mAm.mConstants.mFgsStartRestrictionCheckCallerTargetSdk) {
8972	            return true; // In this case, we only check the service's target SDK level.
8973	        }
8974	        // We always consider SYSTEM_UID to target S+, so just enable the restrictions.
8975	        if (actualCallingUid == Process.SYSTEM_UID) {
8976	            return true;
8977	        }
8978	        if (!CompatChanges.isChangeEnabled(FGS_BG_START_RESTRICTION_CHANGE_ID,
8979	                actualCallingUid)) {
8980	            return false; // If the caller targets < S, then we still disable the restrictions.
8981	        }
8982	
8983	        // Both the service and the caller target S+, so enable the check.
8984	        return true;
8985	    }
