9034	        boolean allowWhileInUsePermissionInFgs;
9035	        @PowerExemptionManager.ReasonCode int fgsStartReasonCode;
9036	        if (state == FOREGROUND_SERVICE_STATE_CHANGED__STATE__ENTER
9037	                || state == FOREGROUND_SERVICE_STATE_CHANGED__STATE__EXIT
9038	                || state == FOREGROUND_SERVICE_STATE_CHANGED__STATE__TIMED_OUT) {
9039	            allowWhileInUsePermissionInFgs = r.mAllowWhileInUsePermissionInFgsAtEntering;
