9044	            fgsStartReasonCode = r.getFgsAllowStart();
9045	        }
9046	        final int callerTargetSdkVersion = r.mRecentCallerApplicationInfo != null
9047	                ? r.mRecentCallerApplicationInfo.targetSdkVersion : 0;
9048	
9049	        // TODO(short-service): Log the UID capabilities (for BFSL) too, and also the procstate?
9050	        FrameworkStatsLog.write(FrameworkStatsLog.FOREGROUND_SERVICE_STATE_CHANGED,
9051	                r.appInfo.uid,
9052	                r.shortInstanceName,
9053	                state,
9054	                allowWhileInUsePermissionInFgs,
9055	                fgsStartReasonCode,
9056	                r.appInfo.targetSdkVersion,
9057	                r.mRecentCallingUid,
9058	                callerTargetSdkVersion,
