9164	    /**
9165	     * Start a foreground service delegate. The delegate is not an actual service component, it is
9166	     * merely a delegate that promotes the client process into foreground service process state.
9167	     *
9168	     * @param options an ForegroundServiceDelegationOptions object.
9169	     * @param connection callback if the delegate is started successfully.
9170	     * @return true if delegate is started, false otherwise.
9171	     * @throw SecurityException if PackageManaager can not resolve
9172	     *        {@link ForegroundServiceDelegationOptions#mClientPackageName} or the resolved
9173	     *        package's UID is not same as {@link ForegroundServiceDelegationOptions#mClientUid}
9174	     */
9175	    boolean startForegroundServiceDelegateLocked(
9176	            @NonNull ForegroundServiceDelegationOptions options,
9177	            @Nullable ServiceConnection connection) {
9178	        Slog.v(TAG, "startForegroundServiceDelegateLocked " + options.getDescription());
9179	        final ComponentName cn = options.getComponentName();
9180	        for (int i = mFgsDelegations.size() - 1; i >= 0; i--) {
9181	            ForegroundServiceDelegation delegation = mFgsDelegations.keyAt(i);
9182	            if (delegation.mOptions.isSameDelegate(options)) {
9183	                Slog.e(TAG, "startForegroundServiceDelegate " + options.getDescription()
9184	                        + " already exists, multiple connections are not allowed");
9185	                return false;
9186	            }
9187	        }
9188	        final int callingPid = options.mClientPid;
9189	        final int callingUid = options.mClientUid;
9190	        final int userId = UserHandle.getUserId(callingUid);
9191	        final String callingPackage = options.mClientPackageName;
9192	
9193	        if (!canStartForegroundServiceLocked(callingPid, callingUid, callingPackage)) {
9194	            Slog.d(TAG, "startForegroundServiceDelegateLocked aborted,"
9195	                    + " app is in the background");
9196	            return false;
9197	        }
9198	
9199	        IApplicationThread caller = options.mClientAppThread;
9200	        ProcessRecord callerApp;
9201	        if (caller != null) {
9202	            callerApp = mAm.getRecordForAppLOSP(caller);
9203	        } else {
9204	            synchronized (mAm.mPidsSelfLocked) {
9205	                callerApp = mAm.mPidsSelfLocked.get(callingPid);
9206	                if (callerApp != null) {
9207	                    caller = callerApp.getThread();
9208	                }
9209	            }
9210	        }
9211	        if (callerApp == null) {
9212	            throw new SecurityException(
9213	                    "Unable to find app for caller " + caller
9214	                            + " (pid=" + callingPid
9215	                            + ") when startForegroundServiceDelegateLocked " + cn);
9216	        }
9217	
9218	        Intent intent = new Intent();
9219	        intent.setComponent(cn);
9220	        ServiceLookupResult res = retrieveServiceLocked(intent, null /*instanceName */,
9221	                false /* isSdkSandboxService */, INVALID_UID /* sdkSandboxClientAppUid */,
9222	                null /* sdkSandboxClientAppPackage */, null /* resolvedType */, callingPackage,
9223	                callingPid, callingUid, userId, true /* createIfNeeded */,
9224	                false /* callingFromFg */, false /* isBindExternal */, false /* allowInstant */ ,
9225	                options, false /* inSharedIsolatedProcess */,
9226	                false /*inPrivateSharedIsolatedProcess*/);
9227	        if (res == null || res.record == null) {
9228	            Slog.d(TAG,
9229	                    "startForegroundServiceDelegateLocked retrieveServiceLocked returns null");
9230	            return false;
9231	        }
9232	
9233	        final ServiceRecord r = res.record;
9234	        r.setProcess(callerApp, caller, callingPid, null);
9235	        r.mIsFgsDelegate = true;
9236	        final ForegroundServiceDelegation delegation =
9237	                new ForegroundServiceDelegation(options, connection);
9238	        r.mFgsDelegation = delegation;
9239	        mFgsDelegations.put(delegation, r);
9240	        mAm.mProcessStateController.setIsForegroundService(r, true);
9241	        r.mFgsEnterTime = SystemClock.uptimeMillis();
9242	        mAm.mProcessStateController.setForegroundServiceType(r, options.mForegroundServiceTypes);
9243	        r.updateOomAdjSeq();
9244	        setFgsRestrictionLocked(callingPackage, callingPid, callingUid, intent, r, userId,
9245	                BackgroundStartPrivileges.NONE,  false /* isBindService */);
9246	        final ProcessServiceRecord psr = callerApp.mServices;
9247	        final boolean newService = mAm.mProcessStateController.startService(psr, r);
9248	        // updateOomAdj.
9249	        updateServiceForegroundLocked(psr, /* oomAdj= */ true);
9250	
9251	        synchronized (mAm.mProcessStats.mLock) {
9252	            final ServiceState stracker = r.getTracker();
9253	            if (stracker != null) {
9254	                stracker.setForeground(true,
9255	                        mAm.mProcessStats.getMemFactorLocked(),
9256	                        SystemClock.uptimeMillis());
9257	            }
9258	        }
9259	
9260	        mAm.mBatteryStatsService.noteServiceStartRunning(callingUid, callingPackage,
9261	                cn.getClassName());
9262	        mAm.mAppOpsService.startOperation(AppOpsManager.getToken(mAm.mAppOpsService),
9263	                AppOpsManager.OP_START_FOREGROUND, r.appInfo.uid, r.packageName, null,
9264	                true, false, null, false,
9265	                AppOpsManager.ATTRIBUTION_FLAGS_NONE, AppOpsManager.ATTRIBUTION_CHAIN_ID_NONE);
9266	        registerAppOpCallbackLocked(r);
9267	        synchronized (mFGSLogger) {
9268	            mFGSLogger.logForegroundServiceStart(r.appInfo.uid, 0, r);
9269	        }
9270	        logFGSStateChangeLocked(r,
9271	                FrameworkStatsLog.FOREGROUND_SERVICE_STATE_CHANGED__STATE__ENTER,
9272	                0, FGS_STOP_REASON_UNKNOWN, FGS_TYPE_POLICY_CHECK_UNKNOWN,
9273	                FOREGROUND_SERVICE_STATE_CHANGED__FGS_START_API__FGSSTARTAPI_DELEGATE,
9274	                false /* fgsRestrictionRecalculated */
9275	        );
9276	        // Notify the caller.
9277	        if (connection != null) {
9278	            mAm.mHandler.post(() -> {
9279	                connection.onServiceConnected(cn, delegation.mBinder);
9280	            });
9281	        }
9282	        signalForegroundServiceObserversLocked(r);
9283	        if (r.foregroundId != 0 && r.foregroundNoti != null) {
9284	            r.foregroundNoti.flags |= Notification.FLAG_FOREGROUND_SERVICE;
9285	            r.postNotification(true);
9286	        }
9287	        return true;
9288	    }
