6164	    private final void sendServiceArgsLocked(ServiceRecord r, boolean execInFg,
6165	            boolean oomAdjusted) throws TransactionTooLargeException {
6166	        final int N = r.pendingStarts.size();
6167	        if (N == 0) {
6168	            return;
6169	        }
6170	
6171	        ArrayList<ServiceStartArgs> args = new ArrayList<>();
6172	
6173	        while (r.pendingStarts.size() > 0) {
6174	            ServiceRecord.StartItem si = r.pendingStarts.remove(0);
6175	            if (DEBUG_SERVICE) {
6176	                Slog.v(TAG_SERVICE, "Sending arguments to: "
6177	                        + r + " " + r.intent + " args=" + si.intent);
6178	            }
6179	            if (si.intent == null && N > 1) {
6180	                // If somehow we got a dummy null intent in the middle,
6181	                // then skip it.  DO NOT skip a null intent when it is
6182	                // the only one in the list -- this is to support the
6183	                // onStartCommand(null) case.
6184	                continue;
6185	            }
6186	            si.deliveredTime = SystemClock.uptimeMillis();
6187	            r.deliveredStarts.add(si);
6188	            si.deliveryCount++;
6189	            if (si.neededGrants != null) {
6190	                mAm.mUgmInternal.grantUriPermissionUncheckedFromIntent(si.neededGrants,
6191	                        si.getUriPermissionsLocked());
6192	            }
6193	            mAm.grantImplicitAccess(r.userId, si.intent, si.callingId,
6194	                    UserHandle.getAppId(r.appInfo.uid)
6195	            );
6196	            bumpServiceExecutingLocked(r, execInFg, "start",
6197	                    OOM_ADJ_REASON_NONE /* use "none" to avoid extra oom adj */,
6198	                    false /* skipTimeoutIfPossible */);
6199	            if (r.fgRequired && !r.fgWaiting) {
6200	                if (!r.isForeground) {
6201	                    if (DEBUG_BACKGROUND_CHECK) {
6202	                        Slog.i(TAG, "Launched service must call startForeground() within timeout: " + r);
6203	                    }
6204	                    scheduleServiceForegroundTransitionTimeoutLocked(r);
6205	                } else {
6206	                    if (DEBUG_BACKGROUND_CHECK) {
6207	                        Slog.i(TAG, "Service already foreground; no new timeout: " + r);
6208	                    }
6209	                    r.fgRequired = false;
6210	                }
6211	            }
6212	            int flags = 0;
6213	            if (si.deliveryCount > 1) {
6214	                flags |= Service.START_FLAG_RETRY;
6215	            }
6216	            if (si.doneExecutingCount > 0) {
6217	                flags |= Service.START_FLAG_REDELIVERY;
6218	            }
6219	            args.add(new ServiceStartArgs(si.taskRemoved, si.id, flags, si.intent));
6220	        }
6221	
6222	        if (!oomAdjusted) {
6223	            mAm.enqueueOomAdjTargetLocked(r.app);
6224	            mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_START_SERVICE);
6225	        }
6226	        ParceledListSlice<ServiceStartArgs> slice = new ParceledListSlice<>(args);
6227	        slice.setInlineCountLimit(4);
6228	        Exception caughtException = null;
6229	        try {
6230	            r.app.getThread().scheduleServiceArgs(r, slice);
6231	        } catch (TransactionTooLargeException e) {
6232	            if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Transaction too large for " + args.size()
6233	                    + " args, first: " + args.get(0).args);
6234	            Slog.w(TAG, "Failed delivering service starts", e);
6235	            caughtException = e;
6236	        } catch (RemoteException e) {
6237	            // Remote process gone...  we'll let the normal cleanup take care of this.
6238	            if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Crashed while sending args: " + r);
6239	            Slog.w(TAG, "Failed delivering service starts", e);
6240	            caughtException = e;
6241	        } catch (Exception e) {
6242	            Slog.w(TAG, "Unexpected exception", e);
6243	            caughtException = e;
6244	        }
6245	
6246	        if (caughtException != null) {
6247	            // Keep nesting count correct
6248	            final boolean inDestroying = mDestroyingServices.contains(r);
6249	            for (int i = 0, size = args.size(); i < size; i++) {
6250	                serviceDoneExecutingLocked(r, inDestroying, inDestroying, true,
6251	                        OOM_ADJ_REASON_STOP_SERVICE);
6252	            }
6253	            /* Will be a no-op if nothing pending */
6254	            mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_STOP_SERVICE);
6255	            if (caughtException instanceof TransactionTooLargeException) {
6256	                throw (TransactionTooLargeException)caughtException;
6257	            }
6258	        }
6259	    }
