6279	    private void bringDownServiceIfNeededLocked(ServiceRecord r, boolean knowConn,
6280	            boolean hasConn, boolean enqueueOomAdj, String debugReason) {
6281	        if (DEBUG_SERVICE) {
6282	            Slog.i(TAG, "Bring down service for " + debugReason + " :" + r.toString());
6283	        }
6284	
6285	        if (isServiceNeededLocked(r, knowConn, hasConn)) {
6286	            return;
6287	        }
6288	
6289	        // Are we in the process of launching?
6290	        if (mPendingServices.contains(r)) {
6291	            return;
6292	        }
6293	
6294	        bringDownServiceLocked(r, enqueueOomAdj);
6295	    }
