6307	
6308	        // Report to all of the connections that the service is no longer
6309	        // available.
6310	        ArrayMap<IBinder, ArrayList<ConnectionRecord>> connections = r.getConnections();
6311	        for (int conni = connections.size() - 1; conni >= 0; conni--) {
6312	            ArrayList<ConnectionRecord> c = connections.valueAt(conni);
6313	            for (int i=0; i<c.size(); i++) {
6314	                ConnectionRecord cr = c.get(i);
6315	                // There is still a connection to the service that is
6316	                // being brought down.  Mark it as dead.
6317	                cr.serviceDead = true;
6318	                cr.stopAssociation();
6319	                final ComponentName clientSideComponentName =
6320	                        cr.aliasComponent != null ? cr.aliasComponent : r.name;
6321	                try {
6322	                    cr.conn.connected(clientSideComponentName, null, true);
6323	                } catch (Exception e) {
6324	                    Slog.w(TAG, "Failure disconnecting service " + r.shortInstanceName
6325	                          + " to connection " + c.get(i).conn.asBinder()
6326	                          + " (in " + c.get(i).binding.client.processName + ")", e);
6327	                }
6328	            }
6329	        }
6330	
6331	        boolean oomAdjusted = Flags.serviceBindingOomAdjPolicy() && r.wasOomAdjUpdated();
6332	
6333	        // Tell the service that it has been unbound.
6334	        if (r.app != null && r.app.isThreadReady()) {
6335	            for (int i = r.bindings.size() - 1; i >= 0; i--) {
6336	                IntentBindRecord ibr = r.bindings.valueAt(i);
6337	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Bringing down binding " + ibr
6338	                        + ": hasBound=" + ibr.hasBound);
6339	                if (ibr.hasBound) {
6340	                    try {
6341	                        bumpServiceExecutingLocked(r, false, "bring down unbind",
6342	                                oomAdjusted ? OOM_ADJ_REASON_NONE : OOM_ADJ_REASON_UNBIND_SERVICE,
6343	                                oomAdjusted /* skipTimeoutIfPossible */);
6344	                        oomAdjusted |= r.wasOomAdjUpdated();
