6359	        // Check to see if the service had been started as foreground, but being
6360	        // brought down before actually showing a notification.  That is not allowed.
6361	        if (r.fgRequired) {
6362	            Slog.w(TAG_SERVICE, "Bringing down service while still waiting for start foreground: "
6363	                    + r);
