6552	    private void dropFgsNotificationStateLocked(ServiceRecord r) {
6553	        if (r.foregroundNoti == null) {
6554	            return;
6555	        }
6556	
6557	        // If this is the only FGS using this notification, clear its FGS flag
6558	        boolean shared = false;
6559	        final ServiceMap smap = mServiceMap.get(r.userId);
6560	        if (smap != null) {
6561	            // Is any other FGS using this notification?
6562	            final int numServices = smap.mServicesByInstanceName.size();
6563	            for (int i = 0; i < numServices; i++) {
6564	                final ServiceRecord sr = smap.mServicesByInstanceName.valueAt(i);
6565	                if (sr == r) {
6566	                    continue;
6567	                }
6568	                if (sr.isForeground
6569	                        && r.foregroundId == sr.foregroundId
6570	                        && r.appInfo.packageName.equals(sr.appInfo.packageName)) {
6571	                    shared = true;
6572	                    break;
6573	                }
6574	            }
6575	        } else {
6576	            Slog.wtf(TAG, "FGS " + r + " not found!");
6577	        }
6578	
6579	        // No other FGS is sharing this notification, so we're done with it
6580	        if (!shared) {
6581	            r.stripForegroundServiceFlagFromNotification();
6582	        }
6583	    }
