6595	                SERVICE_BIND_OOMADJ_POLICY_LEGACY;
6596	        ArrayList<ConnectionRecord> clist = s.getConnections().get(binder);
6597	        if (clist != null) {
6598	            clist.remove(c);
6599	            if (clist.size() == 0) {
6600	                s.removeConnection(binder);
6601	            }
6602	        }
6603	        b.connections.remove(c);
6604	        c.stopAssociation();
6605	        if (c.activity != null && c.activity != skipAct) {
