6621	            }
6622	            // And do the same for bg activity starts ability.
6623	            if (c.hasFlag(Context.BIND_ALLOW_BACKGROUND_ACTIVITY_STARTS)) {
6624	                s.updateIsAllowedBgActivityStartsByBinding();
