6627	            if (c.hasFlag(Context.BIND_ALMOST_PERCEPTIBLE)) {
6628	                mAm.mProcessStateController.updateHasTopStartedAlmostPerceptibleServices(psr);
6629	            }
6630	            if (s.app != null) {
6631	                updateServiceClientActivitiesLocked(s.app.mServices, c, true);
6632	            }
6633	        }
6634	        clist = mServiceConnections.get(binder);
6635	        if (clist != null) {
6636	            clist.remove(c);
6637	            if (clist.size() == 0) {
6638	                mServiceConnections.remove(binder);
6639	            }
6640	        }
6641	
6642	        mAm.stopAssociationLocked(b.client.uid, b.client.processName, s.appInfo.uid,
6643	                s.appInfo.longVersionCode, s.instanceName, s.processName);
6644	
6645	        if (b.connections.size() == 0) {
6646	            b.intent.apps.remove(b.client);
6647	        }
6648	
6649	        if (!c.serviceDead) {
6650	            if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Disconnecting binding " + b.intent
6651	                    + ": shouldUnbind=" + b.intent.hasBound);
6652	            if (s.app != null && s.app.isThreadReady() && b.intent.apps.size() == 0
6653	                    && b.intent.hasBound) {
6654	                serviceBindingOomAdjPolicy = getServiceBindingOomAdjPolicyForRemovalLocked(b.client,
6655	                        s.app, c);
6656	                final boolean skipOomAdj = (serviceBindingOomAdjPolicy
6657	                        & SERVICE_BIND_OOMADJ_POLICY_SKIP_OOM_UPDATE_ON_CONNECT) != 0;
6658	                try {
6659	                    bumpServiceExecutingLocked(s, false, "unbind",
6660	                            skipOomAdj ? OOM_ADJ_REASON_NONE : OOM_ADJ_REASON_UNBIND_SERVICE,
6661	                            skipOomAdj /* skipTimeoutIfPossible */);
6662	                    if (b.client != s.app && c.notHasFlag(Context.BIND_WAIVE_PRIORITY)
6663	                            && s.app.mState.getSetProcState() <= PROCESS_STATE_HEAVY_WEIGHT) {
6664	                        // If this service's process is not already in the cached list,
6665	                        // then update it in the LRU list here because this may be causing
6666	                        // it to go down there and we want it to start out near the top.
6667	                        mAm.updateLruProcessLocked(s.app, false, null);
6668	                    }
6669	                    b.intent.hasBound = false;
6670	                    // Assume the client doesn't want to know about a rebind;
6671	                    // we will deal with that later if it asks for one.
6672	                    b.intent.doRebind = false;
