6705	    void serviceDoneExecutingLocked(ServiceRecord r, int type, int startId, int res,
6706	            boolean enqueueOomAdj, Intent intent) {
6707	        boolean inDestroying = mDestroyingServices.contains(r);
6708	        if (r != null) {
6709	            boolean skipOomAdj = false;
6710	            boolean needOomAdj = false;
6711	            if (type == ActivityThread.SERVICE_DONE_EXECUTING_START) {
6712	                // This is a call from a service start...  take care of
6713	                // book-keeping.
6714	                r.callStart = true;
6715	
6716	                // Set the result to startCommandResult.
6717	                // START_TASK_REMOVED_COMPLETE is _not_ a result from onStartCommand(), so
6718	                // let's ignore.
6719	                if (res != Service.START_TASK_REMOVED_COMPLETE) {
6720	                    r.startCommandResult = res;
6721	                }
6722	                switch (res) {
6723	                    case Service.START_STICKY_COMPATIBILITY:
6724	                    case Service.START_STICKY: {
6725	                        // We are done with the associated start arguments.
6726	                        r.findDeliveredStart(startId, false, true);
6727	                        // Don't stop if killed.
6728	                        r.stopIfKilled = false;
6729	                        break;
6730	                    }
6731	                    case Service.START_NOT_STICKY: {
6732	                        // We are done with the associated start arguments.
6733	                        r.findDeliveredStart(startId, false, true);
6734	                        if (r.getLastStartId() == startId) {
6735	                            // There is no more work, and this service
6736	                            // doesn't want to hang around if killed.
6737	                            r.stopIfKilled = true;
6738	                        }
6739	                        break;
6740	                    }
6741	                    case Service.START_REDELIVER_INTENT: {
6742	                        // We'll keep this item until they explicitly
6743	                        // call stop for it, but keep track of the fact
6744	                        // that it was delivered.
6745	                        ServiceRecord.StartItem si = r.findDeliveredStart(startId, false, false);
6746	                        if (si != null) {
6747	                            si.deliveryCount = 0;
6748	                            si.doneExecutingCount++;
6749	                            // Don't stop if killed.
6750	                            r.stopIfKilled = true;
6751	                        }
6752	                        break;
6753	                    }
6754	                    case Service.START_TASK_REMOVED_COMPLETE: {
6755	                        // Special processing for onTaskRemoved().  Don't
6756	                        // impact normal onStartCommand() processing.
6757	                        r.findDeliveredStart(startId, true, true);
6758	                        break;
6759	                    }
6760	                    default:
6761	                        throw new IllegalArgumentException(
6762	                                "Unknown service start result: " + res);
6763	                }
6764	                if (res == Service.START_STICKY_COMPATIBILITY) {
6765	                    r.callStart = false;
6766	                }
6767	            } else if (type == ActivityThread.SERVICE_DONE_EXECUTING_STOP) {
6768	                // This is the final call from destroying the service...  we should
6769	                // actually be getting rid of the service at this point.  Do some
6770	                // validation of its state, and ensure it will be fully removed.
6771	                if (!inDestroying) {
6772	                    // Not sure what else to do with this...  if it is not actually in the
6773	                    // destroying list, we don't need to make sure to remove it from it.
6774	                    // If the app is null, then it was probably removed because the process died,
6775	                    // otherwise wtf
6776	                    if (r.app != null) {
6777	                        Slog.w(TAG, "Service done with onDestroy, but not inDestroying: "
6778	                                + r + ", app=" + r.app);
6779	                    }
6780	                } else if (r.executeNesting != 1) {
6781	                    Slog.w(TAG, "Service done with onDestroy, but executeNesting="
6782	                            + r.executeNesting + ": " + r);
6783	                    // Fake it to keep from ANR due to orphaned entry.
6784	                    r.executeNesting = 1;
6785	                }
6786	                // The service is done, force an oom adj update.
6787	                needOomAdj = true;
6788	            }
6789	            final long origId = mAm.mInjector.clearCallingIdentity();
6790	            serviceDoneExecutingLocked(r, inDestroying, inDestroying, enqueueOomAdj,
6791	                    !Flags.serviceBindingOomAdjPolicy() || r.wasOomAdjUpdated() || needOomAdj
6792	                    ? OOM_ADJ_REASON_EXECUTING_SERVICE : OOM_ADJ_REASON_NONE);
6793	            mAm.mInjector.restoreCallingIdentity(origId);
6794	        } else {
6795	            Slog.w(TAG, "Done executing unknown service from pid "
6796	                    + mAm.mInjector.getCallingPid());
6797	        }
6798	    }
