6800	    private void serviceProcessGoneLocked(ServiceRecord r, boolean enqueueOomAdj) {
6801	        if (r.tracker != null) {
6802	            synchronized (mAm.mProcessStats.mLock) {
6803	                final int memFactor = mAm.mProcessStats.getMemFactorLocked();
6804	                final long now = SystemClock.uptimeMillis();
6805	                r.tracker.setExecuting(false, memFactor, now);
6806	                r.tracker.setForeground(false, memFactor, now);
6807	                r.tracker.setBound(false, memFactor, now);
6808	                r.tracker.setStarted(false, memFactor, now);
6809	            }
6810	        }
6811	        serviceDoneExecutingLocked(r, true, true, enqueueOomAdj, OOM_ADJ_REASON_PROCESS_END);
6812	    }
