6814	    private void serviceDoneExecutingLocked(ServiceRecord r, boolean inDestroying,
6815	            boolean finishing, boolean enqueueOomAdj, @OomAdjReason int oomAdjReason) {
6816	        if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "<<< DONE EXECUTING " + r
6817	                + ": nesting=" + r.executeNesting
6818	                + ", inDestroying=" + inDestroying + ", app=" + r.app);
6819	        else if (DEBUG_SERVICE_EXECUTING) Slog.v(TAG_SERVICE_EXECUTING,
6820	                "<<< DONE EXECUTING " + r.shortInstanceName);
6821	        r.executeNesting--;
6822	        if (r.executeNesting <= 0) {
6823	            if (r.app != null) {
6824	                final ProcessServiceRecord psr = r.app.mServices;
6825	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE,
6826	                        "Nesting at 0 of " + r.shortInstanceName);
6827	                mAm.mProcessStateController.setExecServicesFg(psr, false);
6828	                mAm.mProcessStateController.stopExecutingService(psr, r);
6829	                if (psr.numberOfExecutingServices() == 0) {
6830	                    if (DEBUG_SERVICE || DEBUG_SERVICE_EXECUTING) Slog.v(TAG_SERVICE_EXECUTING,
6831	                            "No more executingServices of " + r.shortInstanceName);
6832	                    if (r.app.mPid != 0) mActiveServiceAnrTimer.cancel(r.app);
6833	                } else if (r.executeFg) {
6834	                    // Need to re-evaluate whether the app still needs to be in the foreground.
6835	                    for (int i = psr.numberOfExecutingServices() - 1; i >= 0; i--) {
6836	                        if (psr.getExecutingServiceAt(i).executeFg) {
6837	                            mAm.mProcessStateController.setExecServicesFg(psr, true);
6838	                            break;
6839	                        }
6840	                    }
6841	                }
6842	                if (inDestroying) {
6843	                    if (DEBUG_SERVICE) Slog.v(TAG_SERVICE,
6844	                            "doneExecuting remove destroying " + r);
6845	                    mDestroyingServices.remove(r);
6846	                    r.bindings.clear();
6847	                }
6848	                if (oomAdjReason != OOM_ADJ_REASON_NONE) {
6849	                    if (enqueueOomAdj) {
6850	                        mAm.mProcessStateController.enqueueUpdateTarget(r.app);
6851	                    } else {
6852	                        mAm.mProcessStateController.runUpdate(r.app, oomAdjReason);
6853	                    }
6854	                } else {
6855	                    // Skip oom adj if it wasn't bumped during the bumpServiceExecutingLocked()
6856	                }
6857	                r.updateOomAdjSeq();
6858	            }
6859	            r.executeFg = false;
6860	            if (r.tracker != null) {
6861	                synchronized (mAm.mProcessStats.mLock) {
6862	                    final int memFactor = mAm.mProcessStats.getMemFactorLocked();
6863	                    final long now = SystemClock.uptimeMillis();
6864	                    r.tracker.setExecuting(false, memFactor, now);
6865	                    r.tracker.setForeground(false, memFactor, now);
6866	                    if (finishing) {
6867	                        r.tracker.clearCurrentOwner(r, false);
6868	                        r.tracker = null;
6869	                    }
6870	                }
6871	            }
6872	            if (finishing) {
6873	                if (r.app != null && !r.app.isPersistent()) {
6874	                    stopServiceAndUpdateAllowlistManagerLocked(r);
6875	                }
6876	                r.setProcess(null, null, 0, null);
6877	            }
6878	        }
6879	    }
