6881	    boolean attachApplicationLocked(ProcessRecord proc, String processName)
6882	            throws RemoteException {
6883	        boolean didSomething = false;
6884	
6885	        // Update the app background restriction of the caller
6886	        proc.mState.setBackgroundRestricted(appRestrictedAnyInBackground(
6887	                proc.uid, proc.info.packageName));
6888	
6889	        // Collect any services that are waiting for this process to come up.
6890	        if (mPendingServices.size() > 0) {
6891	            ServiceRecord sr = null;
6892	            try {
6893	                for (int i=0; i<mPendingServices.size(); i++) {
6894	                    sr = mPendingServices.get(i);
6895	                    if (proc != sr.isolationHostProc && (proc.uid != sr.appInfo.uid
6896	                            || !processName.equals(sr.processName))) {
6897	                        continue;
6898	                    }
6899	
6900	                    final IApplicationThread thread = proc.getThread();
6901	                    final int pid = proc.getPid();
6902	                    final UidRecord uidRecord = proc.getUidRecord();
6903	                    mPendingServices.remove(i);
6904	                    i--;
6905	                    proc.addPackage(sr.appInfo.packageName, sr.appInfo.longVersionCode,
6906	                            mAm.mProcessStats);
6907	                    try {
6908	                        if (Trace.isTagEnabled(Trace.TRACE_TAG_ACTIVITY_MANAGER)) {
6909	                            Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER,
6910	                                    "realStartServiceLocked: " + sr.shortInstanceName);
6911	                        }
6912	                        realStartServiceLocked(sr, proc, thread, pid, uidRecord, sr.createdFromFg,
6913	                                true, SERVICE_BIND_OOMADJ_POLICY_LEGACY);
6914	                    } finally {
6915	                        Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
6916	                    }
6917	                    didSomething = true;
6918	                    if (!isServiceNeededLocked(sr, false, false)) {
6919	                        // We were waiting for this service to start, but it is actually no
6920	                        // longer needed.  This could happen because bringDownServiceIfNeeded
6921	                        // won't bring down a service that is pending...  so now the pending
6922	                        // is done, so let's drop it.
6923	                        bringDownServiceLocked(sr, true);
6924	                    }
6925	                    /* Will be a no-op if nothing pending */
6926	                    mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_START_SERVICE);
6927	                }
6928	            } catch (RemoteException e) {
6929	                Slog.w(TAG, "Exception in new application when starting service "
6930	                        + sr.shortInstanceName, e);
6931	                throw e;
6932	            }
6933	        }
6934	        // Also, if there are any services that are waiting to restart and
6935	        // would run in this process, now is a good time to start them.  It would
6936	        // be weird to bring up the process but arbitrarily not let the services
6937	        // run at this point just because their restart time hasn't come up.
6938	        if (mRestartingServices.size() > 0) {
6939	            ServiceRecord sr;
6940	            boolean didImmediateRestart = false;
6941	            for (int i=0; i<mRestartingServices.size(); i++) {
6942	                sr = mRestartingServices.get(i);
6943	                if (proc != sr.isolationHostProc && (proc.uid != sr.appInfo.uid
6944	                        || !processName.equals(sr.processName))) {
6945	                    continue;
6946	                }
6947	                mAm.mHandler.removeCallbacks(sr.restarter);
6948	                mAm.mHandler.post(sr.restarter);
6949	                didImmediateRestart = true;
6950	            }
6951	            if (didImmediateRestart) {
6952	                // Since we kicked off all its pending restarts, there could be some open slots
6953	                // in the pending restarts list, schedule a check on it. We are posting to the same
6954	                // handler, so by the time of the check, those immediate restarts should be done.
6955	                mAm.mHandler.post(() -> {
6956	                    final long now = SystemClock.uptimeMillis();
6957	                    synchronized (mAm) {
6958	                        rescheduleServiceRestartIfPossibleLocked(
6959	                                getExtraRestartTimeInBetweenLocked(),
6960	                                mAm.mConstants.SERVICE_MIN_RESTART_TIME_BETWEEN,
6961	                                "other", now);
6962	                    }
6963	                });
6964	            }
6965	        }
6966	        return didSomething;
6967	    }
