6969	    void processStartTimedOutLocked(ProcessRecord proc) {
6970	        boolean needOomAdj = false;
6971	        for (int i = 0, size = mPendingServices.size(); i < size; i++) {
6972	            ServiceRecord sr = mPendingServices.get(i);
6973	            if ((proc.uid == sr.appInfo.uid
6974	                    && proc.processName.equals(sr.processName))
6975	                    || sr.isolationHostProc == proc) {
6976	                Slog.w(TAG, "Forcing bringing down service: " + sr);
