6990	    private boolean collectPackageServicesLocked(String packageName, Set<String> filterByClasses,
6991	            boolean evenPersistent, boolean doit, int minOomAdj,
6992	            ArrayMap<ComponentName, ServiceRecord> services) {
6993	        boolean didSomething = false;
6994	        for (int i = services.size() - 1; i >= 0; i--) {
6995	            ServiceRecord service = services.valueAt(i);
6996	            final boolean sameComponent = packageName == null
6997	                    || (service.packageName.equals(packageName)
6998	                        && (filterByClasses == null
6999	                            || filterByClasses.contains(service.name.getClassName())));
7000	            if (service.app != null && service.app.mState.getCurAdj() < minOomAdj) {
7001	                Slog.i(TAG, "Skip force stopping service " + service
7002	                            + ": below minimum oom adj level");
7003	                continue;
7004	            }
7005	            if (sameComponent
7006	                    && (service.app == null || evenPersistent || !service.app.isPersistent())) {
7007	                if (!doit) {
7008	                    return true;
7009	                }
7010	                didSomething = true;
7011	                Slog.i(TAG, "  Force stopping service " + service);
7012	                if (service.app != null && !service.app.isPersistent()) {
7013	                    stopServiceAndUpdateAllowlistManagerLocked(service);
7014	                }
7015	                service.setProcess(null, null, 0, null);
7016	                service.isolationHostProc = null;
7017	                if (mTmpCollectionResults == null) {
7018	                    mTmpCollectionResults = new ArrayList<>();
7019	                }
7020	                mTmpCollectionResults.add(service);
7021	            }
7022	        }
7023	        return didSomething;
7024	    }
