7032	    boolean bringDownDisabledPackageServicesLocked(String packageName, Set<String> filterByClasses,
7033	            int userId, boolean evenPersistent, boolean fullStop, boolean doit, int minOomAdj) {
7034	        boolean didSomething = false;
7035	
7036	        if (mTmpCollectionResults != null) {
7037	            mTmpCollectionResults.clear();
7038	        }
7039	
7040	        if (userId == UserHandle.USER_ALL) {
7041	            for (int i = mServiceMap.size() - 1; i >= 0; i--) {
7042	                didSomething |= collectPackageServicesLocked(packageName, filterByClasses,
7043	                        evenPersistent, doit, minOomAdj,
7044	                        mServiceMap.valueAt(i).mServicesByInstanceName);
7045	                if (!doit && didSomething) {
7046	                    return true;
7047	                }
7048	                if (doit && filterByClasses == null) {
7049	                    forceStopPackageLocked(packageName, mServiceMap.valueAt(i).mUserId);
7050	                }
7051	            }
7052	        } else {
7053	            ServiceMap smap = mServiceMap.get(userId);
7054	            if (smap != null) {
7055	                ArrayMap<ComponentName, ServiceRecord> items = smap.mServicesByInstanceName;
7056	                didSomething = collectPackageServicesLocked(packageName, filterByClasses,
7057	                        evenPersistent, doit, minOomAdj, items);
7058	            }
7059	            if (doit && filterByClasses == null) {
7060	                forceStopPackageLocked(packageName, userId);
7061	            }
7062	        }
7063	
7064	        if (mTmpCollectionResults != null) {
7065	            final int size = mTmpCollectionResults.size();
7066	            for (int i = size - 1; i >= 0; i--) {
7067	                bringDownServiceLocked(mTmpCollectionResults.get(i), true);
7068	            }
7069	            if (size > 0) {
7070	                mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_COMPONENT_DISABLED);
7071	            }
7072	            if (fullStop && !mTmpCollectionResults.isEmpty()) {
7073	                // if we're tearing down the app's entire service state, account for possible
7074	                // races around FGS notifications by explicitly tidying up in a separate
7075	                // pass post-shutdown
7076	                final ArrayList<ServiceRecord> allServices =
7077	                        (ArrayList<ServiceRecord>) mTmpCollectionResults.clone();
7078	                mAm.mHandler.postDelayed(() -> {
