7105	    @GuardedBy("mAm")
7106	    boolean registerForegroundServiceObserverLocked(final int callingUid,
7107	            IForegroundServiceObserver callback) {
7108	        // We always tell the newly-registered observer about any current FGSes.  The
7109	        // most common case for this is a SysUI crash & relaunch; it needs to
7110	        // reconstruct its tracking of stoppable-FGS-hosting apps.
7111	        try {
7112	            final int mapSize = mServiceMap.size();
7113	            for (int mapIndex = 0; mapIndex < mapSize; mapIndex++) {
7114	                final ServiceMap smap = mServiceMap.valueAt(mapIndex);
7115	                if (smap != null) {
7116	                    final int numServices = smap.mServicesByInstanceName.size();
7117	                    for (int i = 0; i < numServices; i++) {
7118	                        final ServiceRecord sr = smap.mServicesByInstanceName.valueAt(i);
7119	                        if (sr.isForeground && callingUid == sr.appInfo.uid) {
7120	                            callback.onForegroundStateChanged(sr, sr.appInfo.packageName,
7121	                                    sr.userId, true);
7122	                        }
7123	                    }
7124	                }
7125	            }
7126	            // Callback is fine, go ahead and record it
7127	            mFgsObservers.register(callback);
7128	        } catch (RemoteException e) {
7129	            // Whoops, something wrong with the callback.  Don't register it, and
7130	            // report error back to the caller.
7131	            Slog.e(TAG_SERVICE, "Bad FGS observer from uid " + callingUid);
7132	            return false;
7133	        }
7134	
7135	        return true;
7136	    }
