7202	    final void killServicesLocked(ProcessRecord app, boolean allowRestart) {
7203	        final ProcessServiceRecord psr = app.mServices;
7204	        // Report disconnected services.
7205	        if (false) {
7206	            // XXX we are letting the client link to the service for
7207	            // death notifications.
7208	            int numberOfRunningServices = psr.numberOfRunningServices();
7209	            for (int sIndex = 0; sIndex < numberOfRunningServices; sIndex++) {
7210	                ServiceRecord r = psr.getRunningServiceAt(sIndex);
7211	                ArrayMap<IBinder, ArrayList<ConnectionRecord>> connections = r.getConnections();
7212	                for (int conni = connections.size() - 1; conni >= 0; conni--) {
7213	                    ArrayList<ConnectionRecord> cl = connections.valueAt(conni);
7214	                    for (int i = 0; i < cl.size(); i++) {
7215	                        ConnectionRecord c = cl.get(i);
7216	                        if (c.binding.client != app) {
7217	                            try {
7218	                                //c.conn.connected(r.className, null);
7219	                            } catch (Exception e) {
7220	                                // todo: this should be asynchronous!
7221	                                Slog.w(TAG, "Exception thrown disconnected servce "
7222	                                        + r.shortInstanceName
7223	                                        + " from app " + app.processName, e);
7224	                            }
7225	                        }
7226	                    }
7227	                }
7228	            }
7229	        }
7230	
7231	        // Clean up any connections this application has to other services.
7232	        for (int i = psr.numberOfConnections() - 1; i >= 0; i--) {
7233	            ConnectionRecord r = psr.getConnectionAt(i);
7234	            removeConnectionLocked(r, app, null, true);
7235	        }
7236	        updateServiceConnectionActivitiesLocked(psr);
7237	        mAm.mProcessStateController.removeAllConnections(psr);
7238	
7239	        psr.mAllowlistManager = false;
7240	
7241	        // Clear app state from services.
7242	        for (int i = psr.numberOfRunningServices() - 1; i >= 0; i--) {
7243	            ServiceRecord sr = psr.getRunningServiceAt(i);
7244	            mAm.mBatteryStatsService.noteServiceStopLaunch(sr.appInfo.uid, sr.name.getPackageName(),
7245	                    sr.name.getClassName());
7246	            if (sr.app != app && sr.app != null && !sr.app.isPersistent()) {
7247	                mAm.mProcessStateController.stopService(sr.app.mServices, sr);
7248	                sr.app.mServices.updateBoundClientUids();
7249	            }
7250	            sr.setProcess(null, null, 0, null);
7251	            sr.isolationHostProc = null;
7252	            sr.executeNesting = 0;
7253	            synchronized (mAm.mProcessStats.mLock) {
7254	                sr.forceClearTracker();
7255	            }
7256	            if (mDestroyingServices.remove(sr)) {
7257	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "killServices remove destroying " + sr);
7258	            }
7259	
7260	            final int numClients = sr.bindings.size();
7261	            for (int bindingi=numClients-1; bindingi>=0; bindingi--) {
7262	                IntentBindRecord b = sr.bindings.valueAt(bindingi);
7263	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Killing binding " + b
7264	                        + ": shouldUnbind=" + b.hasBound);
7265	                b.binder = null;
7266	                b.requested = b.received = b.hasBound = false;
7267	                // If this binding is coming from a cached process and is asking to keep
7268	                // the service created, then we'll kill the cached process as well -- we
7269	                // don't want to be thrashing around restarting processes that are only
7270	                // there to be cached.
7271	                for (int appi=b.apps.size()-1; appi>=0; appi--) {
7272	                    final ProcessRecord proc = b.apps.keyAt(appi);
7273	                    // If the process is already gone, skip it.
7274	                    if (proc.isKilledByAm() || proc.getThread() == null) {
7275	                        continue;
7276	                    }
7277	                    // Only do this for processes that have an auto-create binding;
7278	                    // otherwise the binding can be left, because it won't cause the
7279	                    // service to restart.
7280	                    final AppBindRecord abind = b.apps.valueAt(appi);
7281	                    boolean hasCreate = false;
7282	                    for (int conni = abind.connections.size() - 1; conni >= 0; conni--) {
7283	                        ConnectionRecord conn = abind.connections.valueAt(conni);
7284	                        if (conn.hasFlag(Context.BIND_AUTO_CREATE)
7285	                                && conn.notHasFlag(Context.BIND_ALLOW_OOM_MANAGEMENT
7286	                                |Context.BIND_WAIVE_PRIORITY)) {
7287	                            hasCreate = true;
7288	                            break;
7289	                        }
7290	                    }
7291	                    if (!hasCreate) {
7292	                        continue;
7293	                    }
7294	                    // XXX turned off for now until we have more time to get a better policy.
7295	                    /*
7296	                    if (false && proc != null && !proc.isPersistent() && proc.getThread() != null
7297	                            && proc.getPid() != 0 && proc.getPid() != ActivityManagerService.MY_PID
7298	                            && proc.mState.getSetProcState() >= PROCESS_STATE_LAST_ACTIVITY) {
7299	                        proc.killLocked("bound to service " + sr.shortInstanceName
7300	                                + " in dying proc " + (app != null ? app.processName : "??"),
7301	                                ApplicationExitInfo.REASON_OTHER, true);
7302	                    }
7303	                    */
7304	                }
7305	            }
7306	        }
7307	
7308	        ServiceMap smap = getServiceMapLocked(app.userId);
7309	
7310	        // Now do remaining service cleanup.
7311	        for (int i = psr.numberOfRunningServices() - 1; i >= 0; i--) {
7312	            ServiceRecord sr = psr.getRunningServiceAt(i);
7313	
7314	            // Unless the process is persistent, this process record is going away,
7315	            // so make sure the service is cleaned out of it.
7316	            if (!app.isPersistent()) {
7317	                mAm.mProcessStateController.stopService(psr, sr);
7318	                psr.updateBoundClientUids();
7319	            }
7320	
7321	            // Check: if the service listed for the app is not one
7322	            // we actually are maintaining, just let it drop.
7323	            final ServiceRecord curRec = smap.mServicesByInstanceName.get(sr.instanceName);
7324	            if (curRec != sr) {
7325	                if (curRec != null) {
7326	                    Slog.wtf(TAG, "Service " + sr + " in process " + app
7327	                            + " not same as in map: " + curRec);
7328	                }
7329	                continue;
7330	            }
7331	
7332	            // Any services running in the application may need to be placed
7333	            // back in the pending list.
7334	            if (allowRestart && sr.crashCount >= mAm.mConstants.BOUND_SERVICE_MAX_CRASH_RETRY
7335	                    && (sr.serviceInfo.applicationInfo.flags
7336	                        &ApplicationInfo.FLAG_PERSISTENT) == 0) {
7337	                Slog.w(TAG, "Service crashed " + sr.crashCount
7338	                        + " times, stopping: " + sr);
7339	                EventLog.writeEvent(EventLogTags.AM_SERVICE_CRASHED_TOO_MUCH,
7340	                        sr.userId, sr.crashCount, sr.shortInstanceName,
7341	                        sr.app != null ? sr.app.getPid() : -1);
7342	                bringDownServiceLocked(sr, true);
7343	            } else if (!allowRestart
7344	                    || !mAm.mUserController.isUserRunning(sr.userId, 0)) {
7345	                bringDownServiceLocked(sr, true);
7346	            } else {
7347	                final boolean scheduled = scheduleServiceRestartLocked(sr, true /* allowCancel */);
7348	
7349	                // Should the service remain running?  Note that in the
7350	                // extreme case of so many attempts to deliver a command
7351	                // that it failed we also will stop it here.
7352	                if (!scheduled) {
7353	                    bringDownServiceLocked(sr, true);
7354	                } else if (sr.canStopIfKilled(false /* isStartCanceled */)) {
7355	                    // Update to stopped state because the explicit start is gone. The service is
7356	                    // scheduled to restart for other reason (e.g. connections) so we don't bring
7357	                    // down it.
7358	                    mAm.mProcessStateController.setStartRequested(sr, false);
7359	                    if (sr.tracker != null) {
7360	                        synchronized (mAm.mProcessStats.mLock) {
7361	                            sr.tracker.setStarted(false, mAm.mProcessStats.getMemFactorLocked(),
7362	                                    SystemClock.uptimeMillis());
7363	                        }
7364	                    }
7365	                }
7366	            }
7367	        }
7368	
7369	        mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_STOP_SERVICE);
7370	
7371	        if (!allowRestart) {
7372	            mAm.mProcessStateController.stopAllServices(psr);
7373	            psr.clearBoundClientUids();
7374	
7375	            // Make sure there are no more restarting services for this process.
7376	            for (int i=mRestartingServices.size()-1; i>=0; i--) {
7377	                ServiceRecord r = mRestartingServices.get(i);
7378	                if (r.processName.equals(app.processName) &&
7379	                        r.serviceInfo.applicationInfo.uid == app.info.uid) {
7380	                    mRestartingServices.remove(i);
7381	                    clearRestartingIfNeededLocked(r);
7382	                }
7383	            }
7384	            for (int i=mPendingServices.size()-1; i>=0; i--) {
7385	                ServiceRecord r = mPendingServices.get(i);
7386	                if (r.processName.equals(app.processName) &&
7387	                        r.serviceInfo.applicationInfo.uid == app.info.uid) {
7388	                    mPendingServices.remove(i);
7389	                }
7390	            }
7391	            for (int i = mPendingBringups.size() - 1; i >= 0; i--) {
7392	                ServiceRecord r = mPendingBringups.keyAt(i);
7393	                if (r.processName.equals(app.processName)
7394	                        && r.serviceInfo.applicationInfo.uid == app.info.uid) {
7395	                    mPendingBringups.removeAt(i);
7396	                }
7397	            }
7398	        }
7399	
7400	        // Make sure we have no more records on the stopping list.
7401	        int i = mDestroyingServices.size();
7402	        while (i > 0) {
7403	            i--;
7404	            ServiceRecord sr = mDestroyingServices.get(i);
7405	            if (sr.app == app) {
7406	                synchronized (mAm.mProcessStats.mLock) {
7407	                    sr.forceClearTracker();
7408	                }
7409	                mDestroyingServices.remove(i);
7410	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "killServices remove destroying " + sr);
7411	            }
7412	        }
7413	
7414	        mAm.mProcessStateController.stopAllExecutingServices(psr);
7415	        psr.noteScheduleServiceTimeoutPending(false);
7416	    }
