7418	    ActivityManager.RunningServiceInfo makeRunningServiceInfoLocked(ServiceRecord r) {
7419	        ActivityManager.RunningServiceInfo info =
7420	            new ActivityManager.RunningServiceInfo();
7421	        info.service = r.name;
7422	        if (r.app != null) {
7423	            info.pid = r.app.getPid();
7424	        }
7425	        info.uid = r.appInfo.uid;
7426	        info.process = r.processName;
7427	        info.foreground = r.isForeground;
7428	        info.activeSince = r.createRealTime;
7429	        info.started = r.startRequested;
7430	        info.clientCount = r.getConnections().size();
7431	        info.crashCount = r.crashCount;
7432	        info.lastActivityTime = r.lastActivity;
7433	        if (r.isForeground) {
7434	            info.flags |= ActivityManager.RunningServiceInfo.FLAG_FOREGROUND;
7435	        }
7436	        if (r.startRequested) {
7437	            info.flags |= ActivityManager.RunningServiceInfo.FLAG_STARTED;
7438	        }
7439	        if (r.app != null && r.app.getPid() == ActivityManagerService.MY_PID) {
7440	            info.flags |= ActivityManager.RunningServiceInfo.FLAG_SYSTEM_PROCESS;
7441	        }
7442	        if (r.app != null && r.app.isPersistent()) {
7443	            info.flags |= ActivityManager.RunningServiceInfo.FLAG_PERSISTENT_PROCESS;
7444	        }
7445	
7446	        ArrayMap<IBinder, ArrayList<ConnectionRecord>> connections = r.getConnections();
7447	        for (int conni = connections.size() - 1; conni >= 0; conni--) {
7448	            ArrayList<ConnectionRecord> connl = connections.valueAt(conni);
7449	            for (int i=0; i<connl.size(); i++) {
7450	                ConnectionRecord conn = connl.get(i);
7451	                if (conn.clientLabel != 0) {
7452	                    info.clientPackage = conn.binding.client.info.packageName;
7453	                    info.clientLabel = conn.clientLabel;
7454	                    return info;
7455	                }
7456	            }
7457	        }
7458	        return info;
7459	    }
