7531	    void serviceTimeout(ProcessRecord proc) {
7532	        try {
7533	            Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER, "serviceTimeout()");
7534	            TimeoutRecord timeoutRecord = null;
7535	            synchronized (mAm) {
7536	                if (proc.isDebugging()) {
7537	                    // The app's being debugged, ignore timeout.
7538	                    mActiveServiceAnrTimer.discard(proc);
7539	                    return;
7540	                }
7541	                final ProcessServiceRecord psr = proc.mServices;
7542	                if (psr.numberOfExecutingServices() == 0 || proc.getThread() == null
7543	                        || proc.isKilled()) {
7544	                    mActiveServiceAnrTimer.discard(proc);
7545	                    return;
7546	                }
7547	                final long now = SystemClock.uptimeMillis();
7548	                final long maxTime =  now
7549	                        - (psr.shouldExecServicesFg()
7550	                        ? mAm.mConstants.SERVICE_TIMEOUT
7551	                        : mAm.mConstants.SERVICE_BACKGROUND_TIMEOUT);
7552	                ServiceRecord timeout = null;
7553	                long nextTime = 0;
7554	                for (int i = psr.numberOfExecutingServices() - 1; i >= 0; i--) {
7555	                    ServiceRecord sr = psr.getExecutingServiceAt(i);
7556	                    if (sr.executingStart < maxTime) {
7557	                        timeout = sr;
7558	                        break;
7559	                    }
7560	                    if (sr.executingStart > nextTime) {
7561	                        nextTime = sr.executingStart;
7562	                    }
7563	                }
7564	                if (timeout != null && mAm.mProcessList.isInLruListLOSP(proc)) {
7565	                    final AutoCloseable timer = mActiveServiceAnrTimer.accept(proc);
7566	                    Slog.w(TAG, "Timeout executing service: " + timeout);
7567	                    StringWriter sw = new StringWriter();
7568	                    PrintWriter pw = new FastPrintWriter(sw, false, 1024);
7569	                    pw.println(timeout);
7570	                    timeout.dump(pw, "    ");
7571	                    pw.close();
7572	                    mLastAnrDump = sw.toString();
7573	                    mAm.mHandler.removeCallbacks(mLastAnrDumpClearer);
7574	                    mAm.mHandler.postDelayed(mLastAnrDumpClearer,
7575	                            LAST_ANR_LIFETIME_DURATION_MSECS);
7576	                    long waitedMillis = now - timeout.executingStart;
7577	                    timeoutRecord = TimeoutRecord.forServiceExec(timeout.shortInstanceName,
7578	                            waitedMillis).setExpiredTimer(timer);
7579	                } else {
7580	                    mActiveServiceAnrTimer.discard(proc);
7581	                    final long delay = psr.shouldExecServicesFg()
7582	                                       ? (nextTime + mAm.mConstants.SERVICE_TIMEOUT) :
7583	                                       (nextTime + mAm.mConstants.SERVICE_BACKGROUND_TIMEOUT)
7584	                                       - SystemClock.uptimeMillis();
7585	                    mActiveServiceAnrTimer.start(proc, delay);
7586	                }
7587	            }
7588	
7589	            if (timeoutRecord != null) {
7590	                mAm.mAnrHelper.appNotResponding(proc, timeoutRecord);
7591	            }
7592	        } finally {
7593	            Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
