7597	    void serviceForegroundTimeout(ServiceRecord r) {
7598	        try {
7599	            Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER, "serviceForegroundTimeout()");
7600	            ProcessRecord app;
7601	            // Create a TimeoutRecord .
7602	            final String annotation = "Context.startForegroundService() did not then call "
7603	                    + "Service.startForeground(): " + r;
7604	            TimeoutRecord timeoutRecord = TimeoutRecord.forServiceStartWithEndTime(annotation,
7605	                    SystemClock.uptimeMillis());
7606	
7607	            timeoutRecord.mLatencyTracker.waitingOnAMSLockStarted();
7608	            synchronized (mAm) {
7609	                timeoutRecord.mLatencyTracker.waitingOnAMSLockEnded();
7610	                if (!r.fgRequired || !r.fgWaiting || r.destroying) {
7611	                    mServiceFGAnrTimer.discard(r);
7612	                    return;
7613	                }
7614	
7615	                app = r.app;
7616	                if (app != null && app.isDebugging()) {
7617	                    // The app's being debugged; let it ride
7618	                    mServiceFGAnrTimer.discard(r);
7619	                    return;
7620	                }
7621	
7622	                mServiceFGAnrTimer.accept(r);
7623	
7624	                if (DEBUG_BACKGROUND_CHECK) {
7625	                    Slog.i(TAG, "Service foreground-required timeout for " + r);
7626	                }
7627	                r.fgWaiting = false;
7628	                stopServiceLocked(r, false);
7629	            }
7630	
7631	            if (app != null) {
7632	
7633	                Message msg = mAm.mHandler.obtainMessage(
7634	                        ActivityManagerService.SERVICE_FOREGROUND_TIMEOUT_ANR_MSG);
7635	                SomeArgs args = SomeArgs.obtain();
7636	                args.arg1 = app;
7637	                args.arg2 = timeoutRecord;
7638	                msg.obj = args;
7639	                mAm.mHandler.sendMessageDelayed(msg,
7640	                        mAm.mConstants.mServiceStartForegroundAnrDelayMs);
7641	            }
7642	        } finally {
7643	            Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
7644	        }
7645	    }
