7921	        private void dumpServiceClient(ServiceRecord r) {
7922	            final ProcessRecord proc = r.app;
7923	            if (proc == null) {
7924	                return;
7925	            }
7926	            final IApplicationThread thread = proc.getThread();
7927	            if (thread == null) {
7928	                return;
7929	            }
7930	            pw.println("    Client:");
7931	            pw.flush();
7932	            try {
7933	                TransferPipe tp = new TransferPipe();
7934	                try {
7935	                    thread.dumpService(tp.getWriteFd(), r, args);
7936	                    tp.setBufferPrefix("      ");
7937	                    // Short timeout, since blocking here can
7938	                    // deadlock with the application.
7939	                    tp.go(fd, 2000);
7940	                } finally {
7941	                    tp.kill();
7942	                }
7943	            } catch (IOException e) {
7944	                pw.println("      Failure while dumping the service: " + e);
7945	            } catch (RemoteException e) {
7946	                pw.println("      Got a RemoteException while dumping the service");
7947	            }
7948	            needSep = true;
7949	        }
