1430	     * Whether the process this service runs in should be temporarily allowed to start
1431	     * activities from background depends on the current state of both
1432	     * {@code mIsAllowedBgActivityStartsByStart} and
1433	     * {@code mIsAllowedBgActivityStartsByBinding}. If either is true, this ServiceRecord
1434	     * should be contributing as a token in parent ProcessRecord.
1435	     *
1436	     * @see com.android.server.am.ProcessRecord#addOrUpdateBackgroundStartPrivileges(Binder,
1437	     *         BackgroundStartPrivileges)
1438	     * @see com.android.server.am.ProcessRecord#removeBackgroundStartPrivileges(Binder)
1439	     */
1440	    private void updateParentProcessBgActivityStartsToken() {
1441	        if (app == null) {
1442	            return;
1443	        }
1444	        BackgroundStartPrivileges backgroundStartPrivileges =
1445	                getBackgroundStartPrivilegesWithExclusiveToken();
1446	        if (backgroundStartPrivileges.allowsAny()) {
1447	            // if the token is already there it's safe to "re-add it" - we're dealing with
1448	            // a set of Binder objects
1449	            app.addOrUpdateBackgroundStartPrivileges(this,
1450	                    backgroundStartPrivileges);
1451	        } else {
1452	            app.removeBackgroundStartPrivileges(this);
1453	        }
1454	    }
