1456	    /**
1457	     * Returns {@link BackgroundStartPrivileges} that represents the privileges a specific
1458	     * originating token or a generic aggregate token.
1459	     *
1460	     * If all privileges are associated with the same token (i.e. the service is only allowed due
1461	     * to starts) the token will be retained, otherwise (e.g. the privileges were granted by
1462	     * bindings) the originating token will be empty.
1463	     */
1464	    @Nullable
1465	    private BackgroundStartPrivileges getBackgroundStartPrivilegesWithExclusiveToken() {
1466	        if (mIsAllowedBgActivityStartsByBinding) {
1467	            return BackgroundStartPrivileges.ALLOW_BAL;
1468	        }
1469	        if (mBackgroundStartPrivilegesByStart.isEmpty()) {
1470	            return BackgroundStartPrivileges.NONE;
1471	        }
1472	        return mBackgroundStartPrivilegesByStartMerged;
1473	    }
