1584	            // Do asynchronous communication with notification manager to
1585	            // avoid deadlocks.
1586	            final String localPackageName = packageName;
1587	            final int localForegroundId = foregroundId;
1588	            final Notification _foregroundNoti = foregroundNoti;
1589	            final ServiceRecord record = this;
1590	            if (DEBUG_FOREGROUND_SERVICE) {
1591	                Slog.d(TAG, "Posting notification " + _foregroundNoti
1592	                        + " for foreground service " + this);
1593	            }
1594	            ams.mHandler.post(new Runnable() {
1595	                public void run() {
1596	                    NotificationManagerInternal nm = LocalServices.getService(
1597	                            NotificationManagerInternal.class);
1598	                    if (nm == null) {
1599	                        return;
1600	                    }
1601	                    // Record whether the package has permission to notify the user
1602	                    mFgsHasNotificationPermission = nm.areNotificationsEnabledForPackage(
1603	                            localPackageName, appUid);
1604	                    Notification localForegroundNoti = _foregroundNoti;
1605	                    try {
1606	                        if (localForegroundNoti.getSmallIcon() == null) {
1607	                            // It is not correct for the caller to not supply a notification
1608	                            // icon, but this used to be able to slip through, so for
1609	                            // those dirty apps we will create a notification clearly
1610	                            // blaming the app.
1611	                            Slog.v(TAG, "Attempted to start a foreground service ("
1612	                                    + shortInstanceName
1613	                                    + ") with a broken notification (no icon: "
1614	                                    + localForegroundNoti
1615	                                    + ")");
1616	
1617	                            CharSequence appName = appInfo.loadLabel(
1618	                                    ams.mContext.getPackageManager());
1619	                            if (appName == null) {
1620	                                appName = appInfo.packageName;
1621	                            }
1622	                            Context ctx = null;
1623	                            try {
1624	                                ctx = ams.mContext.createPackageContextAsUser(
1625	                                        appInfo.packageName, 0, new UserHandle(userId));
1626	
1627	                                Notification.Builder notiBuilder = new Notification.Builder(ctx,
1628	                                        localForegroundNoti.getChannelId());
1629	
1630	                                // it's ugly, but it clearly identifies the app
1631	                                notiBuilder.setSmallIcon(appInfo.icon);
1632	
1633	                                // mark as foreground
1634	                                notiBuilder.setFlag(Notification.FLAG_FOREGROUND_SERVICE, true);
1635	
1636	                                Intent runningIntent = new Intent(
1637	                                        Settings.ACTION_APPLICATION_DETAILS_SETTINGS);
1638	                                runningIntent.setData(Uri.fromParts("package",
1639	                                        appInfo.packageName, null));
1640	                                PendingIntent pi = PendingIntent.getActivityAsUser(ams.mContext, 0,
1641	                                        runningIntent, FLAG_UPDATE_CURRENT | FLAG_IMMUTABLE, null,
1642	                                        UserHandle.of(userId));
1643	                                notiBuilder.setColor(ams.mContext.getColor(
1644	                                        com.android.internal
1645	                                                .R.color.system_notification_accent_color));
1646	                                notiBuilder.setContentTitle(
1647	                                        ams.mContext.getString(
1648	                                                com.android.internal.R.string
1649	                                                        .app_running_notification_title,
1650	                                                appName));
1651	                                notiBuilder.setContentText(
1652	                                        ams.mContext.getString(
1653	                                                com.android.internal.R.string
1654	                                                        .app_running_notification_text,
1655	                                                appName));
1656	                                notiBuilder.setContentIntent(pi);
1657	
1658	                                localForegroundNoti = notiBuilder.build();
1659	                            } catch (PackageManager.NameNotFoundException e) {
1660	                            }
1661	                        }
1662	                        if (nm.getNotificationChannel(localPackageName, appUid,
1663	                                localForegroundNoti.getChannelId()) == null) {
1664	                            int targetSdkVersion = Build.VERSION_CODES.O_MR1;
1665	                            try {
