1406	    /**
1407	     * Defer the service starting/binding until the package is unfrozen, if it's currently frozen.
1408	     *
1409	     * @return {@code true} if the binding is deferred because it's frozen.
1410	     */
1411	    @GuardedBy("mAm")
1412	    private boolean deferServiceBringupIfFrozenLocked(ServiceRecord s, Intent serviceIntent,
1413	            String callingPackage, @Nullable String callingFeatureId,
1414	            int callingUid, int callingPid, String callingProcessName,
1415	            int callingProcessState, boolean fgRequired, boolean callerFg, int userId,
1416	            BackgroundStartPrivileges backgroundStartPrivileges,
1417	            boolean isBinding, IServiceConnection connection) {
1418	        final PackageManagerInternal pm = mAm.getPackageManagerInternal();
1419	        final boolean frozen = pm.isPackageFrozen(s.packageName, callingUid, s.userId);
1420	        if (!frozen) {
1421	            // Not frozen, it's okay to go
1422	            return false;
1423	        }
1424	        ArrayList<Runnable> curPendingBringups = mPendingBringups.get(s);
1425	        if (curPendingBringups == null) {
1426	            curPendingBringups = new ArrayList<>();
1427	            mPendingBringups.put(s, curPendingBringups);
1428	        }
1429	        curPendingBringups.add(new Runnable() {
1430	            @Override
1431	            public void run() {
1432	                synchronized (mAm) {
1433	                    if (!mPendingBringups.containsKey(s)) {
1434	                        return;
1435	                    }
1436	                    // binding request is still valid, so hook them up.
1437	                    // Before doing so, check if it requires a permission review.
1438	                    if (!requestStartTargetPermissionsReviewIfNeededLocked(s,
1439	                                callingPackage, callingFeatureId, callingUid,
1440	                                serviceIntent, callerFg, userId, isBinding, connection)) {
1441	                        // Let's wait for the user approval.
1442	                        return;
1443	                    }
1444	                    if (isBinding) {
1445	                        try {
1446	                            bringUpServiceLocked(s, serviceIntent.getFlags(), callerFg,
1447	                                    false /* whileRestarting */,
1448	                                    false /* permissionsReviewRequired */,
1449	                                    false /* packageFrozen */,
1450	                                    true /* enqueueOomAdj */,
1451	                                    SERVICE_BIND_OOMADJ_POLICY_LEGACY);
1452	                        } catch (TransactionTooLargeException e) {
1453	                            /* ignore - local call */
1454	                        } finally {
1455	                            /* Will be a no-op if nothing pending */
1456	                            mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_START_SERVICE);
1457	                        }
1458	                    } else { // Starting a service
1459	                        try {
1460	                            startServiceInnerLocked(s, serviceIntent, callingUid, callingPid,
1461	                                    callingProcessName, callingProcessState, fgRequired, callerFg,
1462	                                    backgroundStartPrivileges, callingPackage);
1463	                        } catch (TransactionTooLargeException e) {
1464	                            /* ignore - local call */
1465	                        }
1466	                    }
1467	                }
1468	            }
1469	        });
1470	        return true;
1471	    }
