1473	    @GuardedBy("mAm")
1474	    void schedulePendingServiceStartLocked(String packageName, int userId) {
1475	        int totalPendings = mPendingBringups.size();
1476	        for (int i = totalPendings - 1; i >= 0 && totalPendings > 0;) {
1477	            final ServiceRecord r = mPendingBringups.keyAt(i);
1478	            if (r.userId != userId || !TextUtils.equals(r.packageName, packageName)) {
1479	                i--;
1480	                continue;
1481	            }
1482	            final ArrayList<Runnable> curPendingBringups = mPendingBringups.valueAt(i);
1483	            if (curPendingBringups != null) {
1484	                for (int j = curPendingBringups.size() - 1; j >= 0; j--) {
1485	                    curPendingBringups.get(j).run();
1486	                }
1487	                curPendingBringups.clear();
1488	            }
1489	            // Now, how many remaining ones we have after calling into above runnables
1490	            final int curTotalPendings = mPendingBringups.size();
1491	            // Don't call removeAt() here, as it could have been removed already by above runnables
1492	            mPendingBringups.remove(r);
1493	            if (totalPendings != curTotalPendings) {
1494	                // Okay, within the above Runnable.run(), the mPendingBringups is altered.
1495	                // Restart the loop, it won't call into those finished runnables
1496	                // since we've cleared the curPendingBringups above.
1497	                totalPendings = mPendingBringups.size();
1498	                i = totalPendings - 1;
1499	            } else {
1500	                totalPendings = mPendingBringups.size();
1501	                i--;
1502	            }
1503	        }
1504	    }
