1506	    ComponentName startServiceInnerLocked(ServiceMap smap, Intent service, ServiceRecord r,
1507	            boolean callerFg, boolean addToStarting, int callingUid, String callingProcessName,
1508	            int callingProcessState, boolean wasStartRequested, String callingPackage)
1509	            throws TransactionTooLargeException {
1510	        synchronized (mAm.mProcessStats.mLock) {
1511	            final ServiceState stracker = r.getTracker();
1512	            if (stracker != null) {
1513	                stracker.setStarted(true, mAm.mProcessStats.getMemFactorLocked(),
1514	                        SystemClock.uptimeMillis()); // Use current time, not lastActivity.
1515	            }
1516	        }
1517	        r.callStart = false;
1518	
1519	        final int uid = r.appInfo.uid;
1520	        final String packageName = r.name.getPackageName();
1521	        final String serviceName = r.name.getClassName();
1522	        FrameworkStatsLog.write(FrameworkStatsLog.SERVICE_STATE_CHANGED, uid, packageName,
1523	                serviceName, FrameworkStatsLog.SERVICE_STATE_CHANGED__STATE__START);
1524	        mAm.mBatteryStatsService.noteServiceStartRunning(uid, packageName, serviceName);
1525	        final ProcessRecord hostApp = r.app;
1526	        final boolean wasStopped = hostApp == null ? r.appInfo.isStopped() : false;
1527	        final boolean firstLaunch = hostApp == null ? r.appInfo.isNotLaunched() : false;
1528	
1529	        String error = bringUpServiceLocked(r, service.getFlags(), callerFg,
1530	                false /* whileRestarting */,
1531	                false /* permissionsReviewRequired */,
1532	                false /* packageFrozen */,
1533	                true /* enqueueOomAdj */,
1534	                SERVICE_BIND_OOMADJ_POLICY_LEGACY);
1535	        /* Will be a no-op if nothing pending */
1536	        mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_START_SERVICE);
1537	        if (error != null) {
1538	            return new ComponentName("!!", error);
1539	        }
1540	
1541	        final int packageState = wasStopped
1542	                ? SERVICE_REQUEST_EVENT_REPORTED__PACKAGE_STOPPED_STATE__PACKAGE_STATE_STOPPED
1543	                : SERVICE_REQUEST_EVENT_REPORTED__PACKAGE_STOPPED_STATE__PACKAGE_STATE_NORMAL;
1544	        if (DEBUG_PROCESSES) {
1545	            Slog.d(TAG, "Logging startService for " + packageName + ", stopped="
1546	                    + wasStopped + ", firstLaunch=" + firstLaunch + ", intent=" + service
1547	                    + ", r.app=" + r.app);
1548	        }
1549	        FrameworkStatsLog.write(SERVICE_REQUEST_EVENT_REPORTED, uid, callingUid,
1550	                service.getAction(),
1551	                SERVICE_REQUEST_EVENT_REPORTED__REQUEST_TYPE__START, false,
1552	                r.app == null || r.app.getThread() == null
1553	                ? SERVICE_REQUEST_EVENT_REPORTED__PROC_START_TYPE__PROCESS_START_TYPE_COLD
1554	                : (wasStartRequested || !r.getConnections().isEmpty()
1555	                ? SERVICE_REQUEST_EVENT_REPORTED__PROC_START_TYPE__PROCESS_START_TYPE_HOT
1556	                : SERVICE_REQUEST_EVENT_REPORTED__PROC_START_TYPE__PROCESS_START_TYPE_WARM),
1557	                getShortProcessNameForStats(callingUid, callingProcessName),
1558	                getShortServiceNameForStats(r),
1559	                packageState,
1560	                packageName,
1561	                callingPackage,
1562	                callingProcessState,
1563	                r.mProcessStateOnRequest,
1564	                firstLaunch,
1565	                0L /* TODO: stoppedDuration */);
1566	
1567	        if (r.startRequested && addToStarting) {
1568	            boolean first = smap.mStartingBackground.size() == 0;
1569	            smap.mStartingBackground.add(r);
1570	            r.startingBgTimeout = SystemClock.uptimeMillis() + mAm.mConstants.BG_START_TIMEOUT;
1571	            if (DEBUG_DELAYED_SERVICE) {
1572	                RuntimeException here = new RuntimeException("here");
1573	                here.fillInStackTrace();
1574	                Slog.v(TAG_SERVICE, "Starting background (first=" + first + "): " + r, here);
1575	            } else if (DEBUG_DELAYED_STARTS) {
1576	                Slog.v(TAG_SERVICE, "Starting background (first=" + first + "): " + r);
1577	            }
1578	            if (first) {
1579	                smap.rescheduleDelayedStartsLocked();
1580	            }
1581	        } else if (callerFg || r.fgRequired) {
1582	            smap.ensureNotStartingBackgroundLocked(r);
1583	        }
1584	
1585	        return r.name;
1586	    }
