1609	    private void stopServiceLocked(ServiceRecord service, boolean enqueueOomAdj) {
1610	        traceInstant("stopService(): ", service);
1611	        try {
1612	            Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER, "stopServiceLocked()");
1613	            if (service.delayed) {
1614	                // If service isn't actually running, but is being held in the
1615	                // delayed list, then we need to keep it started but note that it
1616	                // should be stopped once no longer delayed.
1617	                if (DEBUG_DELAYED_STARTS) {
1618	                    Slog.v(TAG_SERVICE, "Delaying stop of pending: " + service);
1619	                }
1620	                service.delayedStop = true;
1621	                return;
1622	            }
1623	
1624	            maybeStopShortFgsTimeoutLocked(service);
1625	            maybeStopFgsTimeoutLocked(service);
1626	
1627	            final int uid = service.appInfo.uid;
1628	            final String packageName = service.name.getPackageName();
1629	            final String serviceName = service.name.getClassName();
1630	            FrameworkStatsLog.write(FrameworkStatsLog.SERVICE_STATE_CHANGED, uid, packageName,
1631	                    serviceName, FrameworkStatsLog.SERVICE_STATE_CHANGED__STATE__STOP);
1632	            mAm.mBatteryStatsService.noteServiceStopRunning(uid, packageName, serviceName);
1633	            mAm.mProcessStateController.setStartRequested(service, false);
1634	            if (service.tracker != null) {
1635	                synchronized (mAm.mProcessStats.mLock) {
1636	                    service.tracker.setStarted(false, mAm.mProcessStats.getMemFactorLocked(),
1637	                            SystemClock.uptimeMillis());
1638	                }
1639	            }
1640	            service.callStart = false;
1641	
1642	            bringDownServiceIfNeededLocked(service, false, false, enqueueOomAdj,
1643	                    "stopService");
1644	        } finally {
1645	            Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
1646	        }
1647	
1648	    }
