1879	    boolean foregroundAppShownEnoughLocked(ActiveForegroundApp aa, long nowElapsed) {
1880	        if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "Shown enough: pkg=" + aa.mPackageName + ", uid="
1881	                + aa.mUid);
1882	        boolean canRemove = false;
1883	        aa.mHideTime = Long.MAX_VALUE;
1884	        if (aa.mShownWhileTop) {
1885	            // If the app was ever at the top of the screen while the foreground
1886	            // service was running, then we can always just immediately remove it.
1887	            canRemove = true;
1888	            if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "YES - shown while on top");
1889	        } else if (mScreenOn || aa.mShownWhileScreenOn) {
1890	            final long minTime = aa.mStartVisibleTime
1891	                    + (aa.mStartTime != aa.mStartVisibleTime
1892	                            ? mAm.mConstants.FGSERVICE_SCREEN_ON_AFTER_TIME
1893	                            : mAm.mConstants.FGSERVICE_MIN_SHOWN_TIME);
1894	            if (nowElapsed >= minTime) {
1895	                // If shown while the screen is on, and it has been shown for
1896	                // at least the minimum show time, then we can now remove it.
1897	                if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "YES - shown long enough with screen on");
1898	                canRemove = true;
1899	            } else {
1900	                // This is when we will be okay to stop telling the user.
1901	                long reportTime = nowElapsed + mAm.mConstants.FGSERVICE_MIN_REPORT_TIME;
1902	                aa.mHideTime = reportTime > minTime ? reportTime : minTime;
1903	                if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "NO -- wait " + (aa.mHideTime-nowElapsed)
1904	                        + " with screen on");
1905	            }
1906	        } else {
1907	            final long minTime = aa.mEndTime
1908	                    + mAm.mConstants.FGSERVICE_SCREEN_ON_BEFORE_TIME;
1909	            if (nowElapsed >= minTime) {
1910	                // If the foreground service has only run while the screen is
1911	                // off, but it has been gone now for long enough that we won't
1912	                // care to tell the user about it when the screen comes back on,
1913	                // then we can remove it now.
1914	                if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "YES - gone long enough with screen off");
1915	                canRemove = true;
1916	            } else {
1917	                // This is when we won't care about this old fg service.
1918	                aa.mHideTime = minTime;
1919	                if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "NO -- wait " + (aa.mHideTime-nowElapsed)
1920	                        + " with screen off");
1921	            }
1922	        }
1923	        return canRemove;
1924	    }
