1985	    private void requestUpdateActiveForegroundAppsLocked(ServiceMap smap, long timeElapsed) {
1986	        Message msg = smap.obtainMessage(ServiceMap.MSG_UPDATE_FOREGROUND_APPS);
1987	        if (timeElapsed != 0) {
1988	            smap.sendMessageAtTime(msg,
1989	                    timeElapsed + SystemClock.uptimeMillis() - SystemClock.elapsedRealtime());
1990	        } else {
1991	            smap.mActiveForegroundAppsChanged = true;
1992	            smap.sendMessage(msg);
1993	        }
1994	    }
