1996	    private void decActiveForegroundAppLocked(ServiceMap smap, ServiceRecord r) {
1997	        ActiveForegroundApp active = smap.mActiveForegroundApps.get(r.packageName);
1998	        if (active != null) {
1999	            active.mNumActive--;
2000	            if (active.mNumActive <= 0) {

2001	                active.mEndTime = SystemClock.elapsedRealtime();
2002	                if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "Ended running of service");
2003	                if (foregroundAppShownEnoughLocked(active, active.mEndTime)) {
2004	                    // Have been active for long enough that we will remove it immediately.
2005	                    smap.mActiveForegroundApps.remove(r.packageName);
2006	                    smap.mActiveForegroundAppsChanged = true;
2007	                    requestUpdateActiveForegroundAppsLocked(smap, 0);
2008	                } else if (active.mHideTime < Long.MAX_VALUE){
2009	                    requestUpdateActiveForegroundAppsLocked(smap, active.mHideTime);
2010	                }
2011	            }
2012	        }
2013	    }
