2015	    void updateScreenStateLocked(boolean screenOn) {
2016	        if (mScreenOn != screenOn) {
2017	            mScreenOn = screenOn;
2018	
2019	            // If screen is turning on, then we now reset the start time of any foreground
2020	            // services that were started while the screen was off.
2021	            if (screenOn) {
2022	                final long nowElapsed = SystemClock.elapsedRealtime();
2023	                if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "Screen turned on");
2024	                for (int i = mServiceMap.size()-1; i >= 0; i--) {
2025	                    ServiceMap smap = mServiceMap.valueAt(i);
2026	                    long nextUpdateTime = Long.MAX_VALUE;
2027	                    boolean changed = false;
2028	                    for (int j = smap.mActiveForegroundApps.size()-1; j >= 0; j--) {
2029	                        ActiveForegroundApp active = smap.mActiveForegroundApps.valueAt(j);
2030	                        if (active.mEndTime == 0) {
2031	                            if (!active.mShownWhileScreenOn) {
2032	                                active.mShownWhileScreenOn = true;
2033	                                active.mStartVisibleTime = nowElapsed;
2034	                            }
2035	                        } else {
2036	                            if (!active.mShownWhileScreenOn
2037	                                    && active.mStartVisibleTime == active.mStartTime) {
2038	                                // If this was never shown while the screen was on, then we will
2039	                                // count the time it started being visible as now, to tell the user
2040	                                // about it now that they have a screen to look at.
2041	                                active.mEndTime = active.mStartVisibleTime = nowElapsed;
2042	                            }
2043	                            if (foregroundAppShownEnoughLocked(active, nowElapsed)) {
2044	                                // Have been active for long enough that we will remove it
2045	                                // immediately.
2046	                                smap.mActiveForegroundApps.remove(active.mPackageName);
2047	                                smap.mActiveForegroundAppsChanged = true;
2048	                                changed = true;
2049	                            } else {
2050	                                if (active.mHideTime < nextUpdateTime) {
2051	                                    nextUpdateTime = active.mHideTime;
2052	                                }
2053	                            }
2054	                        }
2055	                    }
2056	                    if (changed) {
2057	                        // Need to immediately update.
2058	                        requestUpdateActiveForegroundAppsLocked(smap, 0);
2059	                    } else if (nextUpdateTime < Long.MAX_VALUE) {
2060	                        requestUpdateActiveForegroundAppsLocked(smap, nextUpdateTime);
2061	                    }
2062	                }
2063	            }
2064	        }
2065	    }
