2092	    /**
2093	     * Check if the given app is allowed to have FGS running even if it's background restricted.
2094	     *
2095	     * <p>
2096	     * Currently it needs to be in Top/Bound Top/FGS state. An uid could be in the FGS state if:
2097	     * a) Bound by another process in the FGS state;
2098	     * b) There is an active FGS running (ServiceRecord.isForeground is true);
2099	     * c) The startForegroundService() has been called but the startForeground() hasn't - in this
2100	     *    case, it must have passed the background FGS start check so we're safe here.
2101	     * </p>
2102	     */
2103	    private boolean isForegroundServiceAllowedInBackgroundRestricted(ProcessRecord app) {
2104	        final ProcessStateRecord state = app.mState;
2105	        if (isDeviceProvisioningPackage(app.info.packageName)) {
2106	            return true;
2107	        }
2108	        if (!state.isBackgroundRestricted()
2109	                || state.getSetProcState() <= ActivityManager.PROCESS_STATE_BOUND_TOP) {
2110	            return true;
2111	        }
2112	        if (state.getSetProcState() == ActivityManager.PROCESS_STATE_FOREGROUND_SERVICE
2113	                && state.isSetBoundByNonBgRestrictedApp()) {
2114	            return true;
2115	        }
2116	        return false;
2117	    }
