2832	    private boolean withinFgsDeferRateLimit(ServiceRecord sr, final long now) {
2833	        // If we're still within the service's deferral period, then by definition
2834	        // deferral is not rate limited.
2835	        if (now < sr.fgDisplayTime) {
2836	            if (DEBUG_FOREGROUND_SERVICE) {
2837	                Slog.d(TAG_SERVICE, "FGS transition for " + sr
2838	                        + " within deferral period, no rate limit applied");
2839	            }
2840	            return false;
2841	        }
2842	
2843	        final int uid = sr.appInfo.uid;
2844	        final long eligible = mFgsDeferralEligible.get(uid, 0L);
2845	        if (DEBUG_FOREGROUND_SERVICE) {
2846	            if (now < eligible) {
2847	                Slog.d(TAG_SERVICE, "FGS transition for uid " + uid
2848	                        + " within rate limit, showing immediately");
2849	            }
2850	        }
2851	        return now < eligible;
2852	    }
