2929	    private class SystemExemptedFgsTypePermission extends ForegroundServiceTypePermission {
2930	        SystemExemptedFgsTypePermission() {
2931	            super("System exempted");
2932	        }
2933	
2934	        @Override
2935	        public int checkPermission(@NonNull Context context, int callerUid, int callerPid,
2936	                @NonNull String packageName, boolean allowWhileInUse) {
2937	            final AppRestrictionController appRestrictionController = mAm.mAppRestrictionController;
2938	            @ReasonCode int reason = appRestrictionController
2939	                    .getPotentialSystemExemptionReason(callerUid);
2940	            if (reason == REASON_DENIED) {
2941	                reason = appRestrictionController
2942	                        .getPotentialSystemExemptionReason(callerUid, packageName);
2943	                if (reason == REASON_DENIED) {
2944	                    reason = appRestrictionController
2945	                            .getPotentialUserAllowedExemptionReason(callerUid, packageName);
2946	                }
2947	            }
2948	            if (reason == REASON_DENIED) {
2949	                if (ArrayUtils.contains(mAm.getPackageManagerInternal().getKnownPackageNames(
2950	                        KnownPackages.PACKAGE_INSTALLER, UserHandle.USER_SYSTEM), packageName)) {
2951	                    reason = REASON_PACKAGE_INSTALLER;
2952	                }
2953	            }
2954	
2955	            switch (reason) {
2956	                case REASON_SYSTEM_UID:
2957	                case REASON_SYSTEM_ALLOW_LISTED:
2958	                case REASON_DEVICE_DEMO_MODE:
2959	                case REASON_DISALLOW_APPS_CONTROL:
2960	                case REASON_DEVICE_OWNER:
2961	                case REASON_PROFILE_OWNER:
2962	                case REASON_PROC_STATE_PERSISTENT:
2963	                case REASON_PROC_STATE_PERSISTENT_UI:
2964	                case REASON_SYSTEM_MODULE:
2965	                case REASON_CARRIER_PRIVILEGED_APP:
2966	                case REASON_DPO_PROTECTED_APP:
2967	                case REASON_ACTIVE_DEVICE_ADMIN:
2968	                case REASON_ROLE_EMERGENCY:
2969	                case REASON_ALLOWLISTED_PACKAGE:
2970	                case REASON_PACKAGE_INSTALLER:
2971	                case REASON_SYSTEM_EXEMPT_APP_OP:
2972	                    return PERMISSION_GRANTED;
2973	                default:
2974	                    return PERMISSION_DENIED;
2975	            }
2976	        }
2977	    }
