580	    /**
581	     * Watch for apps being put into background restricted, so we can step their fg
582	     * services down.
583	     */
584	    class BackgroundRestrictedListener implements AppStateTracker.BackgroundRestrictedAppListener {
585	        @Override
586	        public void updateBackgroundRestrictedForUidPackage(int uid, String packageName,
587	                boolean restricted) {
588	            synchronized (mAm) {
589	                mAm.mProcessList.updateBackgroundRestrictedForUidPackageLocked(
590	                        uid, packageName, restricted);
591	                if (!isForegroundServiceAllowedInBackgroundRestricted(uid, packageName)
592	                        && !isTempAllowedByAlarmClock(uid)) {
593	                    stopAllForegroundServicesLocked(uid, packageName);
594	                }
595	            }
596	        }
597	    }
598	
599	    void stopAllForegroundServicesLocked(final int uid, final String packageName) {
600	        final ServiceMap smap = getServiceMapLocked(UserHandle.getUserId(uid));
601	        final int N = smap.mServicesByInstanceName.size();
602	        final ArrayList<ServiceRecord> toStop = new ArrayList<>(N);
603	        for (int i = 0; i < N; i++) {
604	            final ServiceRecord r = smap.mServicesByInstanceName.valueAt(i);
605	            if (uid == r.serviceInfo.applicationInfo.uid
606	                    || packageName.equals(r.serviceInfo.packageName)) {
607	                // If the FGS is started by temp allowlist of alarm-clock
608	                // (REASON_ALARM_MANAGER_ALARM_CLOCK), allow it to continue and do not stop it,
609	                // even the app is background-restricted.
610	                if (r.isForeground
611	                        && r.mAllowStartForegroundAtEntering != REASON_ALARM_MANAGER_ALARM_CLOCK
612	                        && !isDeviceProvisioningPackage(r.packageName)) {
613	                    toStop.add(r);
614	                }
615	            }
616	        }
617	
618	        // Now stop them all
619	        final int numToStop = toStop.size();
620	        if (numToStop > 0 && DEBUG_FOREGROUND_SERVICE) {
621	            Slog.i(TAG, "Package " + packageName + "/" + uid
622	                    + " in FAS with foreground services");
623	        }
624	        for (int i = 0; i < numToStop; i++) {
625	            final ServiceRecord r = toStop.get(i);
626	            if (DEBUG_FOREGROUND_SERVICE) {
627	                Slog.i(TAG, "  Stopping fg for service " + r);
628	            }
629	            setServiceForegroundInnerLocked(r, 0, null, 0, 0,
630	                    0,  /* systemRequestedTransition= */ true);
631	        }
632	    }
