669	        final ArrayList<DelayingProcess> mStartingProcessList
670	                = new ArrayList<DelayingProcess>();
671	        */
672	
673	        final ArrayList<ServiceRecord> mStartingBackground = new ArrayList<>();
674	
675	        final ArrayMap<String, ActiveForegroundApp> mActiveForegroundApps = new ArrayMap<>();
676	        final ArrayList<String> mPendingRemoveForegroundApps = new ArrayList<>();
677	
678	        boolean mActiveForegroundAppsChanged;
679	
680	        static final int MSG_BG_START_TIMEOUT = 1;
681	        static final int MSG_UPDATE_FOREGROUND_APPS = 2;
682	        static final int MSG_ENSURE_NOT_START_BG = 3;
683	
684	        ServiceMap(Looper looper, int userId) {
685	            super(looper);
686	            mUserId = userId;
687	        }
688	
689	        @Override
690	        public void handleMessage(Message msg) {
691	            switch (msg.what) {
692	                case MSG_BG_START_TIMEOUT: {
693	                    synchronized (mAm) {
694	                        rescheduleDelayedStartsLocked();
695	                    }
696	                } break;
697	                case MSG_UPDATE_FOREGROUND_APPS: {
698	                    updateForegroundApps(this);
699	                } break;
700	                case MSG_ENSURE_NOT_START_BG: {
701	                    synchronized (mAm) {
702	                        rescheduleDelayedStartsLocked();
703	                    }
704	                } break;
705	            }
706	        }
707	
708	        void ensureNotStartingBackgroundLocked(ServiceRecord r) {
709	            if (mStartingBackground.remove(r)) {
710	                if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE,
711	                        "No longer background starting: " + r);
712	                removeMessages(MSG_ENSURE_NOT_START_BG);
713	                Message msg = obtainMessage(MSG_ENSURE_NOT_START_BG);
714	                sendMessage(msg);
715	            }
716	            if (mDelayedStartList.remove(r)) {
717	                if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE, "No longer delaying start: " + r);
718	            }
719	        }
720	
721	        void rescheduleDelayedStartsLocked() {
722	            removeMessages(MSG_BG_START_TIMEOUT);
723	            final long now = SystemClock.uptimeMillis();
724	            for (int i=0, N=mStartingBackground.size(); i<N; i++) {
725	                ServiceRecord r = mStartingBackground.get(i);
726	                if (r.startingBgTimeout <= now) {
727	                    Slog.i(TAG, "Waited long enough for: " + r);
728	                    mStartingBackground.remove(i);
729	                    N--;
730	                    i--;
731	                }
732	            }
733	            while (mDelayedStartList.size() > 0
734	                    && mStartingBackground.size() < mMaxStartingBackground) {
735	                ServiceRecord r = mDelayedStartList.remove(0);
736	                if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE,
737	                        "REM FR DELAY LIST (exec next): " + r);
738	                if (DEBUG_DELAYED_SERVICE) {
739	                    if (mDelayedStartList.size() > 0) {
740	                        Slog.v(TAG_SERVICE, "Remaining delayed list:");
741	                        for (int i=0; i<mDelayedStartList.size(); i++) {
742	                            Slog.v(TAG_SERVICE, "  #" + i + ": " + mDelayedStartList.get(i));
743	                        }
744	                    }
745	                }
746	                r.delayed = false;
747	                if (r.pendingStarts.size() <= 0) {
748	                    Slog.wtf(TAG, "**** NO PENDING STARTS! " + r + " startReq=" + r.startRequested
749	                            + " delayedStop=" + r.delayedStop);
750	                } else {
751	                    try {
752	                        final ServiceRecord.StartItem si = r.pendingStarts.get(0);
753	                        startServiceInnerLocked(this, si.intent, r, false, true, si.callingId,
754	                                si.mCallingProcessName, si.mCallingProcessState,
755	                                r.startRequested, si.mCallingPackageName);
756	                    } catch (TransactionTooLargeException e) {
757	                        // Ignore, nobody upstack cares.
758	                    }
759	                }
760	            }
761	            if (mStartingBackground.size() > 0) {
762	                ServiceRecord next = mStartingBackground.get(0);
763	                long when = next.startingBgTimeout > now ? next.startingBgTimeout : now;
764	                if (DEBUG_DELAYED_SERVICE) Slog.v(TAG_SERVICE, "Top bg start is " + next
765	                        + ", can delay others up to " + when);
766	                Message msg = obtainMessage(MSG_BG_START_TIMEOUT);
767	                sendMessageAtTime(msg, when);
768	            }
769	        }
770	    }
