4554	    boolean unbindServiceLocked(IServiceConnection connection) {
4555	        IBinder binder = connection.asBinder();
4556	        if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "unbindService: conn=" + binder);
4557	        ArrayList<ConnectionRecord> clist = mServiceConnections.get(binder);
4558	        if (clist == null) {
4559	            Slog.w(TAG, "Unbind failed: could not find connection for "
4560	                  + connection.asBinder());
4561	            return false;
4562	        }
4563	
4564	        final int callingPid = mAm.mInjector.getCallingPid();
4565	        final long origId = mAm.mInjector.clearCallingIdentity();
4566	        try {
4567	            if (Trace.isTagEnabled(Trace.TRACE_TAG_ACTIVITY_MANAGER)) {
4568	                String info;
4569	                if (clist.size() > 0) {
4570	                    final ConnectionRecord r = clist.get(0);
4571	                    info = r.binding.service.shortInstanceName + " from " + r.clientProcessName;
4572	                } else {
4573	                    info = Integer.toString(callingPid);
4574	                }
4575	                Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER, "unbindServiceLocked: " + info);
4576	            }
4577	
4578	            boolean needOomAdj = false;
4579	            while (clist.size() > 0) {
4580	                ConnectionRecord r = clist.get(0);
4581	                int serviceBindingOomAdjPolicy = removeConnectionLocked(r, null, null, true);
4582	                if (clist.size() > 0 && clist.get(0) == r) {
4583	                    // In case it didn't get removed above, do it now.
4584	                    Slog.wtf(TAG, "Connection " + r + " not removed for binder " + binder);
4585	                    clist.remove(0);
4586	                }
4587	
4588	                final ProcessRecord app = r.binding.service.app;
4589	                if (app != null) {
4590	                    final ProcessServiceRecord psr = app.mServices;
4591	                    if (psr.mAllowlistManager) {
4592	                        updateAllowlistManagerLocked(psr);
4593	                    }
4594	                    // This could have made the service less important.
4595	                    if (r.hasFlag(Context.BIND_TREAT_LIKE_ACTIVITY)) {
4596	                        // TODO(b/367545398): the following line is a bug. A service unbind
4597	                        //  should potentially lower a process's importance, not elevate it.
4598	                        mAm.mProcessStateController.setTreatLikeActivity(psr, true);
4599	                        mAm.updateLruProcessLocked(app, true, null);
4600	                    }
4601	                    // If the bindee is more important than the binder, we may skip the OomAdjuster.
4602	                    if (serviceBindingOomAdjPolicy == SERVICE_BIND_OOMADJ_POLICY_LEGACY) {
4603	                        mAm.enqueueOomAdjTargetLocked(app);
4604	                        needOomAdj = true;
4605	                    }
4606	                }
4607	            }
4608	
4609	            if (needOomAdj) {
4610	                mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_UNBIND_SERVICE);
4611	            }
4612	
4613	        } finally {
4614	            Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
4615	            mAm.mInjector.restoreCallingIdentity(origId);
4616	        }
4617	
4618	        return true;
4619	    }
