4621	    void unbindFinishedLocked(ServiceRecord r, Intent intent) {
4622	        final long origId = mAm.mInjector.clearCallingIdentity();
4623	        try {
4624	            if (r != null) {
4625	                Intent.FilterComparison filter
4626	                        = new Intent.FilterComparison(intent);
4627	                IntentBindRecord b = r.bindings.get(filter);
4628	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "unbindFinished in " + r
4629	                        + " at " + b + ": apps="
4630	                        + (b != null ? b.apps.size() : 0));
4631	
4632	                boolean inDestroying = mDestroyingServices.contains(r);
4633	                if (b != null) {
4634	                    if (b.apps.size() > 0 && !inDestroying) {
4635	                        // Applications have already bound since the last
4636	                        // unbind, so just rebind right here.
4637	                        boolean inFg = false;
4638	                        for (int i=b.apps.size()-1; i>=0; i--) {
4639	                            ProcessRecord client = b.apps.valueAt(i).client;
4640	                            if (client != null && client.mState.getSetSchedGroup()
4641	                                    != ProcessList.SCHED_GROUP_BACKGROUND) {
4642	                                inFg = true;
4643	                                break;
4644	                            }
4645	                        }
4646	                        try {
4647	                            requestServiceBindingLocked(r, b, inFg, true,
4648	                                    SERVICE_BIND_OOMADJ_POLICY_LEGACY);
4649	                        } catch (TransactionTooLargeException e) {
4650	                            // Don't pass this back to ActivityThread, it's unrelated.
4651	                        }
4652	                    } else {
4653	                        // Note to tell the service the next time there is
4654	                        // a new client.
4655	                        b.doRebind = true;
4656	                    }
4657	                }
4658	
4659	                serviceDoneExecutingLocked(r, inDestroying, false, false,
4660	                        !Flags.serviceBindingOomAdjPolicy() || r.wasOomAdjUpdated()
4661	                        ? OOM_ADJ_REASON_UNBIND_SERVICE : OOM_ADJ_REASON_NONE);
4662	            }
4663	        } finally {
4664	            mAm.mInjector.restoreCallingIdentity(origId);
4665	        }
4666	    }
