5141	    /**
5142	     * Bump the given service record into executing state.
5143	     * @param oomAdjReason The caller requests it to perform the oomAdjUpdate not {@link
5144	     *         ActivityManagerInternal#OOM_ADJ_REASON_NONE}.
5145	     */
5146	    private void bumpServiceExecutingLocked(
5147	            ServiceRecord r, boolean fg, String why, @OomAdjReason int oomAdjReason,
5148	            boolean skipTimeoutIfPossible) {
5149	        if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, ">>> EXECUTING "
5150	                + why + " of " + r + " in app " + r.app);
5151	        else if (DEBUG_SERVICE_EXECUTING) Slog.v(TAG_SERVICE_EXECUTING, ">>> EXECUTING "
5152	                + why + " of " + r.shortInstanceName);
5153	
5154	        // For b/34123235: Services within the system server won't start until SystemServer
5155	        // does Looper.loop(), so we shouldn't try to start/bind to them too early in the boot
5156	        // process. However, since there's a little point of showing the ANR dialog in that case,
5157	        // let's suppress the timeout until PHASE_THIRD_PARTY_APPS_CAN_START.
5158	        //
5159	        // (Note there are multiple services start at PHASE_THIRD_PARTY_APPS_CAN_START too,
5160	        // which technically could also trigger this timeout if there's a system server
5161	        // that takes a long time to handle PHASE_THIRD_PARTY_APPS_CAN_START, but that shouldn't
5162	        // happen.)
5163	        boolean timeoutNeeded = true;
5164	        if ((mAm.mBootPhase < SystemService.PHASE_THIRD_PARTY_APPS_CAN_START)
5165	                && (r.app != null) && (r.app.getPid() == ActivityManagerService.MY_PID)) {
5166	
5167	            Slog.w(TAG, "Too early to start/bind service in system_server: Phase=" + mAm.mBootPhase
5168	                    + " " + r.getComponentName());
5169	            timeoutNeeded = false;
5170	        }
5171	
5172	        // If the process is frozen or to be frozen, and we want to skip the timeout, skip it.
5173	        final boolean shouldSkipTimeout = skipTimeoutIfPossible && r.app != null
5174	                && (r.app.mOptRecord.isPendingFreeze() || r.app.mOptRecord.isFrozen());
5175	
5176	        ProcessServiceRecord psr;
5177	        if (r.executeNesting == 0) {
5178	            r.executeFg = fg;
5179	            synchronized (mAm.mProcessStats.mLock) {
5180	                final ServiceState stracker = r.getTracker();
5181	                if (stracker != null) {
5182	                    stracker.setExecuting(true, mAm.mProcessStats.getMemFactorLocked(),
5183	                            SystemClock.uptimeMillis());
5184	                }
5185	            }
5186	            if (r.app != null) {
5187	                psr = r.app.mServices;
5188	                mAm.mProcessStateController.startExecutingService(psr, r);
5189	                mAm.mProcessStateController.setExecServicesFg(psr,
5190	                        psr.shouldExecServicesFg() || fg);
5191	                if (timeoutNeeded && psr.numberOfExecutingServices() == 1) {
5192	                    if (!shouldSkipTimeout) {
5193	                        scheduleServiceTimeoutLocked(r.app);
5194	                    } else {
5195	                        r.app.mServices.noteScheduleServiceTimeoutPending(true);
5196	                    }
5197	                }
5198	            }
5199	        } else if (r.app != null && fg) {
5200	            psr = r.app.mServices;
5201	            if (!psr.shouldExecServicesFg()) {
5202	                mAm.mProcessStateController.setExecServicesFg(psr, true);
5203	                if (timeoutNeeded) {
5204	                    if (!shouldSkipTimeout) {
5205	                        scheduleServiceTimeoutLocked(r.app);
5206	                    } else {
5207	                        r.app.mServices.noteScheduleServiceTimeoutPending(true);
5208	                    }
5209	                }
5210	            }
5211	        }
5212	        if (r.app != null
5213	                && r.app.mState.getCurProcState() > ActivityManager.PROCESS_STATE_SERVICE) {
5214	            // Enqueue the oom adj target anyway for opportunistic oom adj updates.
5215	            mAm.enqueueOomAdjTargetLocked(r.app);
5216	            r.updateOomAdjSeq();
5217	            if (oomAdjReason != OOM_ADJ_REASON_NONE) {
5218	                // Force an immediate oomAdjUpdate, so the client app could be in the correct
5219	                // process state before doing any service related transactions
5220	                mAm.updateOomAdjPendingTargetsLocked(oomAdjReason);
5221	            }
5222	        }
5223	        r.executeFg |= fg;
5224	        r.executeNesting++;
5225	        r.executingStart = SystemClock.uptimeMillis();
5226	    }
