5228	    private final boolean requestServiceBindingLocked(ServiceRecord r, IntentBindRecord i,
5229	            boolean execInFg, boolean rebind,
5230	            @ServiceBindingOomAdjPolicy int serviceBindingOomAdjPolicy)
5231	            throws TransactionTooLargeException {
5232	        if (r.app == null || r.app.getThread() == null) {
5233	            // If service is not currently running, can't yet bind.
5234	            return false;
5235	        }
5236	        if (DEBUG_SERVICE) Slog.d(TAG_SERVICE, "requestBind " + i + ": requested=" + i.requested
5237	                + " rebind=" + rebind);
5238	        final boolean skipOomAdj = (serviceBindingOomAdjPolicy
5239	                & SERVICE_BIND_OOMADJ_POLICY_SKIP_OOM_UPDATE_ON_BIND) != 0;
5240	        if ((!i.requested || rebind) && i.apps.size() > 0) {
5241	            try {
5242	                bumpServiceExecutingLocked(r, execInFg, "bind",
5243	                        skipOomAdj ? OOM_ADJ_REASON_NONE : OOM_ADJ_REASON_BIND_SERVICE,
5244	                        skipOomAdj /* skipTimeoutIfPossible */);
5245	                if (Trace.isTagEnabled(Trace.TRACE_TAG_ACTIVITY_MANAGER)) {
5246	                    Trace.instant(Trace.TRACE_TAG_ACTIVITY_MANAGER, "requestServiceBinding="
5247	                            + i.intent.getIntent() + ". bindSeq=" + mBindServiceSeqCounter);
5248	                }
5249	                r.app.getThread().scheduleBindService(r, i.intent.getIntent(), rebind,
5250	                        r.app.mState.getReportedProcState(), mBindServiceSeqCounter++);
5251	                if (!rebind) {
5252	                    i.requested = true;
5253	                }
5254	                i.hasBound = true;
5255	                i.doRebind = false;
5256	            } catch (TransactionTooLargeException e) {
5257	                // Keep the executeNesting count accurate.
5258	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Crashed while binding " + r, e);
5259	                final boolean inDestroying = mDestroyingServices.contains(r);
5260	                serviceDoneExecutingLocked(r, inDestroying, inDestroying, false,
5261	                        !Flags.serviceBindingOomAdjPolicy() || r.wasOomAdjUpdated()
5262	                        ? OOM_ADJ_REASON_UNBIND_SERVICE : OOM_ADJ_REASON_NONE);
5263	                throw e;
5264	            } catch (RemoteException e) {
5265	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Crashed while binding " + r);
5266	                // Keep the executeNesting count accurate.
5267	                final boolean inDestroying = mDestroyingServices.contains(r);
5268	                serviceDoneExecutingLocked(r, inDestroying, inDestroying, false,
5269	                        !Flags.serviceBindingOomAdjPolicy() || r.wasOomAdjUpdated()
5270	                        ? OOM_ADJ_REASON_UNBIND_SERVICE : OOM_ADJ_REASON_NONE);
5271	                return false;
5272	            }
5273	        }
5274	        return true;
5275	    }
