5286	        if (smap.mServicesByInstanceName.get(r.instanceName) != r) {
5287	            ServiceRecord cur = smap.mServicesByInstanceName.get(r.instanceName);
5288	            Slog.wtf(TAG, "Attempting to schedule restart of " + r
5289	                    + " when found in map: " + cur);
