5291	        }
5292	
5293	        final long now = SystemClock.uptimeMillis();
5294	
5295	        final String reason;
5296	        final int oldPosInRestarting = mRestartingServices.indexOf(r);
5297	        boolean inRestarting = oldPosInRestarting != -1;
5298	        if ((r.serviceInfo.applicationInfo.flags
5299	                &ApplicationInfo.FLAG_PERSISTENT) == 0) {
5300	            long minDuration = mAm.mConstants.SERVICE_RESTART_DURATION;
5301	            long resetTime = mAm.mConstants.SERVICE_RESET_RUN_DURATION;
5302	            boolean canceled = false;
5303	
5304	            // Any delivered but not yet finished starts should be put back
5305	            // on the pending list.
5306	            final int N = r.deliveredStarts.size();
5307	            if (N > 0) {
5308	                for (int i=N-1; i>=0; i--) {
5309	                    ServiceRecord.StartItem si = r.deliveredStarts.get(i);
5310	                    si.removeUriPermissionsLocked();
5311	                    if (si.intent == null) {
5312	                        // We'll generate this again if needed.
5313	                    } else if (!allowCancel || (si.deliveryCount < ServiceRecord.MAX_DELIVERY_COUNT
5314	                            && si.doneExecutingCount < ServiceRecord.MAX_DONE_EXECUTING_COUNT)) {
5315	                        r.pendingStarts.add(0, si);
5316	                        long dur = SystemClock.uptimeMillis() - si.deliveredTime;
5317	                        dur *= 2;
5318	                        if (minDuration < dur) minDuration = dur;
5319	                        if (resetTime < dur) resetTime = dur;
