5333	                    return false;
5334	                }
5335	                reason = (r.startRequested && !shouldStop) ? "start-requested" : "connection";
5336	            } else {
5337	                reason = "always";
5338	            }
5339	
5340	            r.totalRestartCount++;
5341	            if (r.restartDelay == 0) {
5342	                r.restartCount++;
5343	                r.restartDelay = minDuration;
5344	            } else if (r.crashCount > 1) {
5345	                r.restartDelay = mAm.mConstants.BOUND_SERVICE_CRASH_RESTART_DURATION
5346	                        * (r.crashCount - 1);
5347	            } else {
5348	                // If it has been a "reasonably long time" since the service
5349	                // was started, then reset our restart duration back to
5350	                // the beginning, so we don't infinitely increase the duration
5351	                // on a service that just occasionally gets killed (which is
5352	                // a normal case, due to process being killed to reclaim memory).
5353	                if (now > (r.restartTime+resetTime)) {
5354	                    r.restartCount = 1;
5355	                    r.restartDelay = minDuration;
5356	                } else {
5357	                    r.restartDelay *= mAm.mConstants.SERVICE_RESTART_DURATION_FACTOR;
5358	                    if (r.restartDelay < minDuration) {
5359	                        r.restartDelay = minDuration;
5360	                    }
5361	                }
5362	            }
5363	
5364	            if (isServiceRestartBackoffEnabledLocked(r.packageName)) {
5365	                r.nextRestartTime = r.mEarliestRestartTime = now + r.restartDelay;
5366	
5367	                if (inRestarting) {
5368	                    // Take it out of the list temporarily for easier maintenance of the list.
5369	                    mRestartingServices.remove(oldPosInRestarting);
5370	                    inRestarting = false;
5371	                }
5372	                if (mRestartingServices.isEmpty()) {
5373	                    // Apply the extra delay even if it's the only one in the list.
5374	                    final long extraDelay = getExtraRestartTimeInBetweenLocked();
5375	                    r.nextRestartTime = Math.max(now + extraDelay, r.nextRestartTime);
5376	                    r.restartDelay = r.nextRestartTime - now;
5377	                } else {
5378	                    // Make sure that we don't end up restarting a bunch of services
5379	                    // all at the same time.
5380	                    boolean repeat;
5381	                    final long restartTimeBetween = getExtraRestartTimeInBetweenLocked()
5382	                            + mAm.mConstants.SERVICE_MIN_RESTART_TIME_BETWEEN;
5383	                    do {
5384	                        repeat = false;
5385	                        final long nextRestartTime = r.nextRestartTime;
5386	                        // mRestartingServices is sorted by nextRestartTime.
5387	                        for (int i = mRestartingServices.size() - 1; i >= 0; i--) {
5388	                            final ServiceRecord r2 = mRestartingServices.get(i);
5389	                            final long nextRestartTime2 = r2.nextRestartTime;
5390	                            if (nextRestartTime >= (nextRestartTime2 - restartTimeBetween)
5391	                                    && nextRestartTime < (nextRestartTime2 + restartTimeBetween)) {
5392	                                r.nextRestartTime = nextRestartTime2 + restartTimeBetween;
5393	                                r.restartDelay = r.nextRestartTime - now;
5394	                                repeat = true;
5395	                                break;
5396	                            } else if (nextRestartTime >= nextRestartTime2 + restartTimeBetween) {
5397	                                // This spot fulfills our needs, bail out.
5398	                                break;
5399	                            }
5400	                        }
5401	                    } while (repeat);
5402	                }
5403	            } else {
5404	                // It's been forced to ignore the restart backoff, fix the delay here.
5405	                r.restartDelay = mAm.mConstants.SERVICE_RESTART_DURATION;
5406	                r.nextRestartTime = now + r.restartDelay;
5407	            }
5408	        } else {
5409	            // Persistent processes are immediately restarted, so there is no
5410	            // reason to hold of on restarting their services.
5411	            r.totalRestartCount++;
5412	            r.restartCount = 0;
5413	            r.restartDelay = 0;
5414	            r.mEarliestRestartTime = 0;
5415	            r.nextRestartTime = now;
5416	            reason = "persistent";
5417	        }
5418	
5419	        r.mRestartSchedulingTime = now;
5420	        if (!inRestarting) {
5421	            if (oldPosInRestarting == -1) {
5422	                r.createdFromFg = false;
5423	                synchronized (mAm.mProcessStats.mLock) {
5424	                    r.makeRestarting(mAm.mProcessStats.getMemFactorLocked(),
5425	                            SystemClock.uptimeMillis());
5426	                }
5427	            }
5428	            boolean added = false;
5429	            for (int i = 0, size = mRestartingServices.size(); i < size; i++) {
5430	                final ServiceRecord r2 = mRestartingServices.get(i);
5431	                if (r2.nextRestartTime > r.nextRestartTime) {
5432	                    mRestartingServices.add(i, r);
5433	                    added = true;
5434	                    break;
5435	                }
5436	            }
5437	            if (!added) {
5438	                mRestartingServices.add(r);
5439	            }
5440	        }
5441	
5442	        cancelForegroundNotificationLocked(r);
5443	
5444	        performScheduleRestartLocked(r, "Scheduling", reason, now);
5445	
5446	        return true;
5447	    }
