5449	    @GuardedBy("mAm")
5450	    void performScheduleRestartLocked(ServiceRecord r, @NonNull String scheduling,
5451	            @NonNull String reason, @UptimeMillisLong long now) {
5452	
5453	        // If the service is waiting to become a foreground service, remove the pending
5454	        // SERVICE_FOREGROUND_TIMEOUT_MSG msg, and set fgWaiting to false, so next time the service
5455	        // is brought up, scheduleServiceForegroundTransitionTimeoutLocked() can be called again and
5456	        // a new SERVICE_FOREGROUND_TIMEOUT_MSG is scheduled in SERVICE_START_FOREGROUND_TIMEOUT
5457	        // again.
5458	        if (r.fgRequired && r.fgWaiting) {
5459	            mServiceFGAnrTimer.cancel(r);
5460	            r.fgWaiting = false;
5461	        }
5462	
5463	        mAm.mHandler.removeCallbacks(r.restarter);
5464	        mAm.mHandler.postAtTime(r.restarter, r.nextRestartTime);
5465	        r.nextRestartTime = now + r.restartDelay;
5466	        Slog.w(TAG, scheduling + " restart of crashed service "
5467	                + r.shortInstanceName + " in " + r.restartDelay + "ms for " + reason);
5468	        EventLog.writeEvent(EventLogTags.AM_SCHEDULE_SERVICE_RESTART,
5469	                r.userId, r.shortInstanceName, r.restartDelay);
5470	    }
