5487	        performRescheduleServiceRestartOnMemoryPressureLocked(
5488	                mAm.mConstants.mExtraServiceRestartDelayOnMemPressure[prevMemFactor],
5489	                mAm.mConstants.mExtraServiceRestartDelayOnMemPressure[curMemFactor], reason, now);
