5492	    /**
5493	     * Reschedule service restarts based on if the extra delays are enabled or not.
5494	     *
5495	     * @param prevEnabled The previous state of whether or not it's enabled.
5496	     * @param curEnabled The current state of whether or not it's enabled.
5497	     * @param now The uptimeMillis
5498	     */
5499	    @GuardedBy("mAm")
5500	    void rescheduleServiceRestartOnMemoryPressureIfNeededLocked(boolean prevEnabled,
5501	            boolean curEnabled, @UptimeMillisLong long now) {
5502	        if (prevEnabled == curEnabled) {
5503	            return;
5504	        }
5505	        final @MemFactor int memFactor = mAm.mAppProfiler.getLastMemoryLevelLocked();
5506	        final long delay = mAm.mConstants.mExtraServiceRestartDelayOnMemPressure[memFactor];
