5573	    @GuardedBy("mAm")
5574	    void performRescheduleServiceRestartOnMemoryPressureLocked(long oldExtraDelay,
5575	            long newExtraDelay, @NonNull String reason, @UptimeMillisLong long now) {
5576	        final long delta = newExtraDelay - oldExtraDelay;
5577	        if (delta == 0) {
5578	            return;
5579	        }
5580	        if (delta > 0) {
5581	            final long restartTimeBetween = mAm.mConstants.SERVICE_MIN_RESTART_TIME_BETWEEN
5582	                    + newExtraDelay;
5583	            long lastRestartTime = now;
5584	            // Make the delay in between longer.
5585	            for (int i = 0, size = mRestartingServices.size(); i < size; i++) {
5586	                final ServiceRecord r = mRestartingServices.get(i);
5587	                if ((r.serviceInfo.applicationInfo.flags & ApplicationInfo.FLAG_PERSISTENT) != 0
5588	                        || !isServiceRestartBackoffEnabledLocked(r.packageName)) {
5589	                    lastRestartTime = r.nextRestartTime;
5590	                    continue;
5591	                }
5592	                boolean reschedule = false;
5593	                if (lastRestartTime <= now) {
5594	                    // It hasn't moved, this is the first one (besides persistent process),
5595	                    // we don't need to insert the minRestartTimeBetween for it, but need
5596	                    // the newExtraDelay still.
5597	                    final long oldVal = r.nextRestartTime;
5598	                    r.nextRestartTime = Math.max(now, Math.max(r.mEarliestRestartTime,
5599	                            r.mRestartSchedulingTime + newExtraDelay));
5600	                    reschedule = r.nextRestartTime != oldVal;
5601	                } else if (r.nextRestartTime - lastRestartTime < restartTimeBetween) {
5602	                    r.nextRestartTime = Math.max(lastRestartTime + restartTimeBetween, now);
5603	                    reschedule = true;
5604	                }
5605	                r.restartDelay = r.nextRestartTime - now;
5606	                lastRestartTime = r.nextRestartTime;
5607	                if (reschedule) {
5608	                    performScheduleRestartLocked(r, "Rescheduling", reason, now);
5609	                }
5610	            }
5611	        } else if (delta < 0) {
5612	            // Make the delay in between shorter, we'd do a rescan and reschedule.
5613	            rescheduleServiceRestartIfPossibleLocked(newExtraDelay,
5614	                    mAm.mConstants.SERVICE_MIN_RESTART_TIME_BETWEEN, reason, now);
5615	        }
5616	    }
