5651	    private final boolean unscheduleServiceRestartLocked(ServiceRecord r, int callingUid,
5652	            boolean force) {
5653	        if (!force && r.restartDelay == 0) {
5654	            return false;
5655	        }
5656	        // Remove from the restarting list; if the service is currently on the
5657	        // restarting list, or the call is coming from another app, then this
5658	        // service has become of much more interest so we reset the restart interval.
5659	        boolean removed = mRestartingServices.remove(r);
5660	        if (removed || callingUid != r.appInfo.uid) {
5661	            r.resetRestartCounter();
5662	        }
5663	        if (removed) {
5664	            clearRestartingIfNeededLocked(r);
5665	        }
5666	        mAm.mHandler.removeCallbacks(r.restarter);
5667	        return true;
5668	    }
