5740	    private String bringUpServiceLocked(ServiceRecord r, int intentFlags, boolean execInFg,
5741	            boolean whileRestarting, boolean permissionsReviewRequired, boolean packageFrozen,
5742	            boolean enqueueOomAdj, @ServiceBindingOomAdjPolicy int serviceBindingOomAdjPolicy)
5743	            throws TransactionTooLargeException {
5744	        try {
5745	            if (Trace.isTagEnabled(Trace.TRACE_TAG_ACTIVITY_MANAGER)) {
5746	                Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER,
5747	                        "bringUpServiceLocked: " + r.shortInstanceName);
5748	            }
5749	            return bringUpServiceInnerLocked(r, intentFlags, execInFg, whileRestarting,
5750	                    permissionsReviewRequired, packageFrozen, enqueueOomAdj,
5751	                    serviceBindingOomAdjPolicy);
5752	        } finally {
5753	            Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
5754	        }
5755	    }
5756	
5757	    private String bringUpServiceInnerLocked(ServiceRecord r, int intentFlags, boolean execInFg,
5758	            boolean whileRestarting, boolean permissionsReviewRequired, boolean packageFrozen,
5759	            boolean enqueueOomAdj, @ServiceBindingOomAdjPolicy int serviceBindingOomAdjPolicy)
5760	            throws TransactionTooLargeException {
5761	        if (r.app != null && r.app.isThreadReady()) {
5762	            r.updateOomAdjSeq();
5763	            sendServiceArgsLocked(r, execInFg, false);
5764	            return null;
5765	        }
5766	
5767	        if (!whileRestarting && mRestartingServices.contains(r)) {
5768	            // If waiting for a restart, then do nothing.
5769	            return null;
5770	        }
5771	
5772	        final long startTimeNs = SystemClock.elapsedRealtimeNanos();
5773	
5774	        if (DEBUG_SERVICE) {
5775	            Slog.v(TAG_SERVICE, "Bringing up " + r + " " + r.intent + " fg=" + r.fgRequired);
5776	        }
5777	
5778	        // We are now bringing the service up, so no longer in the
5779	        // restarting state.
5780	        if (mRestartingServices.remove(r)) {
5781	            clearRestartingIfNeededLocked(r);
5782	        }
5783	
5784	        // Make sure this service is no longer considered delayed, we are starting it now.
5785	        if (r.delayed) {
5786	            if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE, "REM FR DELAY LIST (bring up): " + r);
5787	            getServiceMapLocked(r.userId).mDelayedStartList.remove(r);
5788	            r.delayed = false;
5789	        }
5790	
5791	        // Make sure that the user who owns this service is started.  If not,
5792	        // we don't want to allow it to run.
5793	        if (!mAm.mUserController.hasStartedUserState(r.userId)) {
5794	            String msg = "Unable to launch app "
5795	                    + r.appInfo.packageName + "/"
5796	                    + r.appInfo.uid + " for service "
5797	                    + r.intent.getIntent() + ": user " + r.userId + " is stopped";
5798	            Slog.w(TAG, msg);
5799	            bringDownServiceLocked(r, enqueueOomAdj);
5800	            return msg;
5801	        }
5802	
5803	        // Report usage if binding is from a different package except for explicitly exempted
5804	        // bindings
5805	        if (!r.appInfo.packageName.equals(r.mRecentCallingPackage)
5806	                && !r.isNotAppComponentUsage) {
5807	            mAm.mUsageStatsService.reportEvent(
5808	                    r.packageName, r.userId, UsageEvents.Event.APP_COMPONENT_USED);
5809	        }
5810	
5811	        try {
5812	            mAm.mPackageManagerInt.notifyComponentUsed(
5813	                    r.packageName, r.userId, r.mRecentCallingPackage, r.toString());
5814	        } catch (IllegalArgumentException e) {
5815	            Slog.w(TAG, "Failed trying to unstop package "
5816	                    + r.packageName + ": " + e);
5817	        }
5818	
5819	        final boolean isolated = (r.serviceInfo.flags&ServiceInfo.FLAG_ISOLATED_PROCESS) != 0;
5820	        final String procName = r.processName;
5821	        HostingRecord hostingRecord = new HostingRecord(
5822	                HostingRecord.HOSTING_TYPE_SERVICE, r.instanceName,
5823	                r.definingPackageName, r.definingUid, r.serviceInfo.processName,
5824	                getHostingRecordTriggerType(r));
5825	        ProcessRecord app;
5826	
