3086	    // No legacy-app behavior skew intended but there's a runtime E-stop if a need
3087	    // arises, so note that
3088	    @SuppressWarnings("AndroidFrameworkCompatChange")
3089	    private boolean shouldShowFgsNotificationLocked(ServiceRecord r) {
3090	        final long now = SystemClock.uptimeMillis();
3091	
3092	        // Is the behavior enabled at all?
3093	        if (!mAm.mConstants.mFlagFgsNotificationDeferralEnabled) {
3094	            return true;
3095	        }
3096	
3097	        // Has this service's deferral timer expired?
3098	        if (r.mFgsNotificationDeferred && now >= r.fgDisplayTime) {
3099	            if (DEBUG_FOREGROUND_SERVICE) {
3100	                Slog.d(TAG, "FGS reached end of deferral period: " + r);
3101	            }
3102	            return true;
3103	        }
3104	
3105	        // Did the app have another FGS notification deferred recently?
3106	        if (withinFgsDeferRateLimit(r, now)) {
3107	            return true;
3108	        }
3109	
3110	        if (mAm.mConstants.mFlagFgsNotificationDeferralApiGated) {
3111	            // Legacy apps' FGS notifications are also deferred unless the relevant
3112	            // DeviceConfig element has been set
3113	            final boolean isLegacyApp = (r.appInfo.targetSdkVersion < Build.VERSION_CODES.S);
3114	            if (isLegacyApp) {
3115	                return true;
3116	            }
3117	        }
3118	
3119	        // did we already show it?
3120	        if (r.mFgsNotificationShown) {
3121	            return true;
3122	        }
3123	
3124	        // has the app forced deferral?
3125	        if (!r.foregroundNoti.isForegroundDisplayForceDeferred()) {
3126	            // is the notification such that it should show right away?
3127	            if (r.foregroundNoti.shouldShowForegroundImmediately()) {
3128	                if (DEBUG_FOREGROUND_SERVICE) {
3129	                    Slog.d(TAG_SERVICE, "FGS " + r
3130	                            + " notification policy says show immediately");
3131	                }
3132	                return true;
3133	            }
3134	
3135	            // or is this an type of FGS that always shows immediately?
3136	            if ((r.foregroundServiceType & FGS_IMMEDIATE_DISPLAY_MASK) != 0) {
3137	                if (DEBUG_FOREGROUND_SERVICE) {
3138	                    Slog.d(TAG_SERVICE, "FGS " + r
3139	                            + " type gets immediate display");
3140	                }
3141	                return true;
3142	            }
3143	
3144	            // fall through to return false: no policy dictates immediate display
3145	        } else {
3146	            if (DEBUG_FOREGROUND_SERVICE) {
3147	                Slog.d(TAG_SERVICE, "FGS " + r + " notification is app deferred");
3148	            }
3149	            // fall through to return false
3150	        }
3151	
3152	        return false;
3153	    }
