3155	    // Target SDK consultation here is strictly for logging purposes, not
3156	    // behavioral variation.
3157	    @SuppressWarnings("AndroidFrameworkCompatChange")
3158	    private void startFgsDeferralTimerLocked(ServiceRecord r) {
3159	        final long now = SystemClock.uptimeMillis();
3160	        final int uid = r.appInfo.uid;
3161	
3162	        // schedule the actual notification post
3163	        long when = now
3164	                + (r.isShortFgs() ? mAm.mConstants.mFgsNotificationDeferralIntervalForShort
3165	                : mAm.mConstants.mFgsNotificationDeferralInterval);
3166	        // If there are already deferred FGS notifications for this app,
3167	        // inherit that deferred-show timestamp
3168	        for (int i = 0; i < mPendingFgsNotifications.size(); i++) {
3169	            final ServiceRecord pending = mPendingFgsNotifications.get(i);
3170	            if (pending == r) {
3171	                // Already pending; no need to reschedule
3172	                if (DEBUG_FOREGROUND_SERVICE) {
3173	                    Slog.d(TAG_SERVICE, "FGS " + r
3174	                            + " already pending notification display");
3175	                }
3176	                return;
3177	            }
3178	            if (uid == pending.appInfo.uid) {
3179	                when = Math.min(when, pending.fgDisplayTime);
3180	            }
3181	        }
3182	
3183	        if (mFgsDeferralRateLimited) {
3184	            final long nextEligible = when
3185	                    + (r.isShortFgs() ? mAm.mConstants.mFgsNotificationDeferralExclusionTimeForShort
3186	                    : mAm.mConstants.mFgsNotificationDeferralExclusionTime);
3187	            mFgsDeferralEligible.put(uid, nextEligible);
3188	        }
3189	        r.fgDisplayTime = when;
3190	        r.mFgsNotificationDeferred = true;
3191	        r.mFgsNotificationWasDeferred = true;
3192	        r.mFgsNotificationShown = false;
3193	        mPendingFgsNotifications.add(r);
3194	        if (DEBUG_FOREGROUND_SERVICE) {
3195	            Slog.d(TAG_SERVICE, "FGS " + r
3196	                    + " notification in " + (when - now) + " ms");
3197	        }
3198	        final boolean isLegacyApp = (r.appInfo.targetSdkVersion < Build.VERSION_CODES.S);
3199	        if (isLegacyApp) {
3200	            Slog.i(TAG_SERVICE, "Deferring FGS notification in legacy app "
3201	                    + r.appInfo.packageName + "/" + UserHandle.formatUid(r.appInfo.uid)
3202	                    + " : " + r.foregroundNoti);
3203	        }
3204	        mAm.mHandler.postAtTime(mPostDeferredFGSNotifications, when);
3205	    }
3206	
3207	    private final Runnable mPostDeferredFGSNotifications = new Runnable() {
3208	        @Override
3209	        public void run() {
3210	            if (DEBUG_FOREGROUND_SERVICE) {
3211	                Slog.d(TAG_SERVICE, "+++ evaluating deferred FGS notifications +++");
3212	            }
3213	            final long now = SystemClock.uptimeMillis();
3214	            synchronized (mAm) {
3215	                // post all notifications whose time has come
3216	                for (int i = mPendingFgsNotifications.size() - 1; i >= 0; i--) {
3217	                    final ServiceRecord r = mPendingFgsNotifications.get(i);
3218	                    if (r.fgDisplayTime <= now) {
3219	                        if (DEBUG_FOREGROUND_SERVICE) {
3220	                            Slog.d(TAG_SERVICE, "FGS " + r
3221	                                    + " handling deferred notification now");
3222	                        }
3223	                        mPendingFgsNotifications.remove(i);
3224	                        // The service might have been stopped or exited foreground state
3225	                        // in the interval, so we lazy check whether we still need to show
3226	                        // the notification.
3227	                        if (r.isForeground && r.app != null) {
3228	                            r.postNotification(true);
3229	                            r.mFgsNotificationShown = true;
3230	                        } else {
3231	                            if (DEBUG_FOREGROUND_SERVICE) {
3232	                                Slog.d(TAG_SERVICE, "  - service no longer running/fg, ignoring");
3233	                            }
3234	                        }
3235	                    }
3236	                }
3237	                if (DEBUG_FOREGROUND_SERVICE) {
3238	                    Slog.d(TAG_SERVICE, "Done evaluating deferred FGS notifications; "
3239	                            + mPendingFgsNotifications.size() + " remaining");
3240	                }
3241	            }
3242	        }
3243	    };
