3573	    /**
3574	     * Update a {@link ServiceRecord}'s {@link ShortFgsInfo} as needed, and also start
3575	     * a timeout as needed.
3576	     *
3577	     * If the {@link ServiceRecord} is not a short-FGS, then we'll stop the timeout and clear
3578	     * the {@link ShortFgsInfo}.
3579	     */
3580	    private void maybeUpdateShortFgsTrackingLocked(ServiceRecord sr,
3581	            boolean extendTimeout) {
3582	        if (!sr.isShortFgs()) {
3583	            mAm.mProcessStateController.clearShortFgsInfo(sr); // Just in case we have it.
3584	            unscheduleShortFgsTimeoutLocked(sr);
3585	            return;
3586	        }
3587	
3588	        final boolean isAlreadyShortFgs = sr.hasShortFgsInfo();
3589	
3590	        if (extendTimeout || !isAlreadyShortFgs) {
3591	            if (DEBUG_SHORT_SERVICE) {
3592	                if (isAlreadyShortFgs) {
3593	                    Slog.i(TAG_SERVICE, "Extending SHORT_SERVICE time out: " + sr);
3594	                } else {
3595	                    Slog.i(TAG_SERVICE, "Short FGS started: " + sr);
3596	                }
3597	            }
3598	            traceInstant("short FGS start/extend: ", sr);
3599	            mAm.mProcessStateController.setShortFgsInfo(sr, SystemClock.uptimeMillis());
3600	
3601	            // We'll restart the timeout.
3602	            unscheduleShortFgsTimeoutLocked(sr);
3603	
3604	            final Message msg = mAm.mHandler.obtainMessage(
3605	                    ActivityManagerService.SERVICE_SHORT_FGS_TIMEOUT_MSG, sr);
3606	            mAm.mHandler.sendMessageAtTime(msg, sr.getShortFgsInfo().getTimeoutTime());
3607	        } else {
3608	            if (DEBUG_SHORT_SERVICE) {
3609	                Slog.w(TAG_SERVICE, "NOT extending SHORT_SERVICE time out: " + sr);
3610	            }
3611	
3612	            // We only (potentially) update the start command, start count, but not the timeout
3613	            // time.
3614	            // In this case, we keep the existing timeout running.
3615	            sr.getShortFgsInfo().update();
3616	        }
3617	    }
