3633	    void onShortFgsTimeout(ServiceRecord sr) {
3634	        synchronized (mAm) {
3635	            final long nowUptime = SystemClock.uptimeMillis();
3636	            if (!sr.shouldTriggerShortFgsTimeout(nowUptime)) {
3637	                if (DEBUG_SHORT_SERVICE) {
3638	                    Slog.d(TAG_SERVICE, "[STALE] Short FGS timed out: " + sr
3639	                            + " " + sr.getShortFgsTimedEventDescription(nowUptime));
3640	                }
3641	                return;
3642	            }
3643	            Slog.e(TAG_SERVICE, "Short FGS timed out: " + sr);
3644	            traceInstant("short FGS timeout: ", sr);
3645	
3646	            logFGSStateChangeLocked(sr,
3647	                    FOREGROUND_SERVICE_STATE_CHANGED__STATE__TIMED_OUT,
3648	                    nowUptime > sr.mFgsEnterTime ? (int) (nowUptime - sr.mFgsEnterTime) : 0,
3649	                    FGS_STOP_REASON_UNKNOWN,
3650	                    FGS_TYPE_POLICY_CHECK_UNKNOWN,
3651	                    FOREGROUND_SERVICE_STATE_CHANGED__FGS_START_API__FGSSTARTAPI_NA,
3652	                    false /* fgsRestrictionRecalculated */
3653	            );
3654	            try {
3655	                sr.app.getThread().scheduleTimeoutService(sr, sr.getShortFgsInfo().getStartId());
3656	            } catch (RemoteException e) {
3657	                Slog.w(TAG_SERVICE, "Exception from scheduleTimeoutService: " + e.toString());
3658	            }
3659	            // Schedule the procstate demotion timeout and ANR timeout.
3660	            {
3661	                final Message msg = mAm.mHandler.obtainMessage(
3662	                        ActivityManagerService.SERVICE_SHORT_FGS_PROCSTATE_TIMEOUT_MSG, sr);
3663	                mAm.mHandler.sendMessageAtTime(
3664	                        msg, sr.getShortFgsInfo().getProcStateDemoteTime());
3665	            }
3666	
3667	            // ServiceRecord.getAnrTime() is an absolute time with a reference that is not "now".
3668	            // Compute the time from "now" when starting the anr timer.
3669	            mShortFGSAnrTimer.start(sr,
3670	                    sr.getShortFgsInfo().getAnrTime() - SystemClock.uptimeMillis());
3671	        }
3672	    }
