3745	    /**
3746	     * @return the fgs type for this service which has the most lenient time limit; if none of the
3747	     * types are time-restricted, return {@link ServiceInfo#FOREGROUND_SERVICE_TYPE_NONE}.
3748	     */
3749	    @ServiceInfo.ForegroundServiceType int getTimeLimitedFgsType(int foregroundServiceType) {
3750	        int fgsType = ServiceInfo.FOREGROUND_SERVICE_TYPE_NONE;
3751	        long timeout = 0;
3752	        if ((foregroundServiceType & ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROCESSING)
3753	                == ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROCESSING) {
3754	            fgsType = ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROCESSING;
3755	            timeout = mAm.mConstants.mMediaProcessingFgsTimeoutDuration;
3756	        }
3757	        if ((foregroundServiceType & ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC)
3758	                == ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC) {
3759	            // update the timeout and type if this type has a more lenient time limit
3760	            if (timeout == 0 || mAm.mConstants.mDataSyncFgsTimeoutDuration > timeout) {
3761	                fgsType = ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC;
3762	                timeout = mAm.mConstants.mDataSyncFgsTimeoutDuration;
3763	            }
3764	        }
3765	        // Add logic for time limits introduced in the future for other fgs types above.
3766	        return fgsType;
3767	    }
