3769	    /**
3770	     * @return the constant time limit defined for the given foreground service type.
3771	     */
3772	    private long getTimeLimitForFgsType(int foregroundServiceType) {
3773	        return switch (foregroundServiceType) {
3774	            case ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROCESSING ->
3775	                    mAm.mConstants.mMediaProcessingFgsTimeoutDuration;
3776	            case ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC ->
3777	                    mAm.mConstants.mDataSyncFgsTimeoutDuration;
3778	            // Add logic for time limits introduced in the future for other fgs types above.
3779	            default -> Long.MAX_VALUE;
3780	        };
3781	    }
