3783	    /**
3784	     * @return the next stop time for the given type, based on how long it has already ran for.
3785	     * The total runtime is automatically reset 24hrs after the first fgs start of this type
3786	     * or if the app has recently been in the TOP state when the app calls startForeground().
3787	     */
3788	    private long getNextFgsStopTime(int fgsType, TimeLimitedFgsInfo fgsInfo) {
3789	        final long timeLimit = getTimeLimitForFgsType(fgsType);
3790	        if (timeLimit == Long.MAX_VALUE) {
3791	            return Long.MAX_VALUE;
3792	        }
3793	        return fgsInfo.getLastFgsStartTime() + Math.max(0, timeLimit - fgsInfo.getTotalRuntime());
3794	    }
