3804	    private void maybeUpdateFgsTrackingLocked(ServiceRecord sr, int previousFgsType) {
3805	        final int previouslyTimeLimitedType = getTimeLimitedFgsType(previousFgsType);
3806	        if (previouslyTimeLimitedType == ServiceInfo.FOREGROUND_SERVICE_TYPE_NONE
3807	                && !sr.isFgsTimeLimited()) {
3808	            // FGS was not previously time-limited and new type isn't either.
3809	            return;
3810	        }
3811	
3812	        if (previouslyTimeLimitedType != ServiceInfo.FOREGROUND_SERVICE_TYPE_NONE) {
3813	            // FGS is switching types and the previous type was time-limited so update the runtime.
3814	            final TimeLimitedFgsInfo fgsTypeInfo = getFgsTimeLimitedInfo(
3815	                                                    sr.appInfo.uid, previouslyTimeLimitedType);
3816	            if (fgsTypeInfo != null) {
3817	                // Update the total runtime for the previous time-limited fgs type.
3818	                fgsTypeInfo.updateTotalRuntime(SystemClock.uptimeMillis());
3819	                fgsTypeInfo.decNumParallelServices();
3820	            }
3821	
3822	            if (!sr.isFgsTimeLimited()) {
3823	                // Reset timers since new type does not have a timeout.
3824	                mAm.mHandler.removeMessages(ActivityManagerService.SERVICE_FGS_TIMEOUT_MSG, sr);
3825	                mAm.mHandler.removeMessages(
3826	                                ActivityManagerService.SERVICE_FGS_CRASH_TIMEOUT_MSG, sr);
3827	                return;
3828	            }
3829	        }
3830	
3831	        traceInstant("FGS start: ", sr);
3832	        final long nowUptime = SystemClock.uptimeMillis();
3833	
3834	        // Fetch/create/update the fgs info for the time-limited type.
3835	        SparseArray<TimeLimitedFgsInfo> fgsInfo = mTimeLimitedFgsInfo.get(sr.appInfo.uid);
3836	        if (fgsInfo == null) {
3837	            fgsInfo = new SparseArray<>();
3838	            mTimeLimitedFgsInfo.put(sr.appInfo.uid, fgsInfo);
3839	        }
3840	        final int timeLimitedFgsType = getTimeLimitedFgsType(sr.foregroundServiceType);
3841	        TimeLimitedFgsInfo fgsTypeInfo = fgsInfo.get(timeLimitedFgsType);
3842	        if (fgsTypeInfo == null) {
3843	            fgsTypeInfo = sr.createTimeLimitedFgsInfo();
3844	            fgsInfo.put(timeLimitedFgsType, fgsTypeInfo);
3845	        }
3846	        fgsTypeInfo.noteFgsFgsStart(nowUptime);
3847	
3848	        // We'll cancel the timeout and crash messages and post a fresh one below.
3849	        mAm.mHandler.removeMessages(ActivityManagerService.SERVICE_FGS_TIMEOUT_MSG, sr);
3850	        mAm.mHandler.removeMessages(ActivityManagerService.SERVICE_FGS_CRASH_TIMEOUT_MSG, sr);
3851	
3852	        final Message msg = mAm.mHandler.obtainMessage(
3853	                ActivityManagerService.SERVICE_FGS_TIMEOUT_MSG, sr);
3854	        final long timeoutCallbackTime = getNextFgsStopTime(timeLimitedFgsType, fgsTypeInfo);
3855	        if (timeoutCallbackTime == Long.MAX_VALUE) {
3856	            // This should never happen since we only get to this point if the service record's
3857	            // foregroundServiceType attribute contains a type that can be timed-out.
3858	            Slog.wtf(TAG, "Couldn't calculate timeout for time-limited fgs: " + sr);
3859	            return;
