3902	    void onFgsTimeout(ServiceRecord sr) {
3903	        synchronized (mAm) {
3904	            final int fgsType = getTimeLimitedFgsType(sr.foregroundServiceType);
3905	            if (fgsType == ServiceInfo.FOREGROUND_SERVICE_TYPE_NONE || sr.app == null) {
3906	                mAm.mHandler.removeMessages(
3907	                                ActivityManagerService.SERVICE_FGS_CRASH_TIMEOUT_MSG, sr);
3908	                return;
3909	            }
3910	
3911	            final boolean currentlyTop = sr.app.mState.getCurProcState() <= PROCESS_STATE_TOP;
3912	            final long nowUptime = SystemClock.uptimeMillis();
3913	            final long lastTopTime = currentlyTop ? nowUptime : sr.app.mState.getLastTopTime();
3914	            final long constantTimeLimit = getTimeLimitForFgsType(fgsType);
3915	            if (lastTopTime != Long.MIN_VALUE && constantTimeLimit > (nowUptime - lastTopTime)) {
3916	                // Discard any other messages for this service
3917	                mAm.mHandler.removeMessages(ActivityManagerService.SERVICE_FGS_TIMEOUT_MSG, sr);
3918	                mAm.mHandler.removeMessages(
3919	                                ActivityManagerService.SERVICE_FGS_CRASH_TIMEOUT_MSG, sr);
3920	                // The app was in the TOP state after the FGS was started so its time allowance
3921	                // should be counted from that time since this is considered a user interaction
3922	                final Message msg = mAm.mHandler.obtainMessage(
3923	                                        ActivityManagerService.SERVICE_FGS_TIMEOUT_MSG, sr);
3924	                mAm.mHandler.sendMessageAtTime(msg, lastTopTime + constantTimeLimit);
3925	                return;
3926	            }
3927	
3928	            Slog.e(TAG_SERVICE, "FGS (" + ServiceInfo.foregroundServiceTypeToLabel(fgsType)
3929	                    + ") timed out: " + sr);
3930	            traceInstant("FGS timed out: ", sr);
3931	
3932	            final TimeLimitedFgsInfo fgsTypeInfo = getFgsTimeLimitedInfo(sr.appInfo.uid, fgsType);
3933	            if (fgsTypeInfo != null) {
3934	                // Update total runtime for the time-limited fgs type and mark it as timed out.
3935	                fgsTypeInfo.updateTotalRuntime(nowUptime);
3936	                fgsTypeInfo.setTimeLimitExceededAt(nowUptime);
3937	
3938	                logFGSStateChangeLocked(sr,
3939	                        FOREGROUND_SERVICE_STATE_CHANGED__STATE__TIMED_OUT,
3940	                        nowUptime > fgsTypeInfo.getFirstFgsStartUptime()
3941	                                ? (int) (nowUptime - fgsTypeInfo.getFirstFgsStartUptime()) : 0,
3942	                        FGS_STOP_REASON_UNKNOWN,
3943	                        FGS_TYPE_POLICY_CHECK_UNKNOWN,
3944	                        FOREGROUND_SERVICE_STATE_CHANGED__FGS_START_API__FGSSTARTAPI_NA,
3945	                        false /* fgsRestrictionRecalculated */
3946	                );
3947	            }
3948	
3949	            try {
3950	                sr.app.getThread().scheduleTimeoutServiceForType(sr, sr.getLastStartId(), fgsType);
3951	            } catch (RemoteException e) {
3952	                Slog.w(TAG_SERVICE, "Exception from scheduleTimeoutServiceForType: " + e);
3953	            }
3954	
3955	            // Crash the service after giving the service some time to clean up.
3956	            final Message msg = mAm.mHandler.obtainMessage(
3957	                                    ActivityManagerService.SERVICE_FGS_CRASH_TIMEOUT_MSG, sr);
3958	            mAm.mHandler.sendMessageDelayed(msg, mAm.mConstants.mFgsCrashExtraWaitDuration);
3959	        }
3960	    }
