3962	    void onFgsCrashTimeout(ServiceRecord sr) {
3963	        final int fgsType = getTimeLimitedFgsType(sr.foregroundServiceType);
3964	        if (fgsType == ServiceInfo.FOREGROUND_SERVICE_TYPE_NONE) {
3965	            return; // no timed out FGS type was found (either it was stopped or it switched types)
3966	        }
3967	
3968	        synchronized (mAm) {
3969	            final TimeLimitedFgsInfo fgsTypeInfo = getFgsTimeLimitedInfo(sr.appInfo.uid, fgsType);
3970	            if (fgsTypeInfo != null) {
3971	                // Runtime is already updated when the service times out - if the app didn't
3972	                // stop the service, decrement the number of parallel running services here.
3973	                fgsTypeInfo.decNumParallelServices();
3974	            }
3975	
3976	            final String reason = "A foreground service of type "
3977	                    + ServiceInfo.foregroundServiceTypeToLabel(fgsType)
3978	                    + " did not stop within its timeout: " + sr.getComponentName();
3979	            if (android.app.Flags.enableFgsTimeoutCrashBehavior()) {
3980	                // Crash the app
3981	                Slog.e(TAG_SERVICE, "FGS Crashed: " + sr);
3982	                traceInstant("FGS Crash: ", sr);
3983	                if (sr.app != null) {
3984	                    mAm.crashApplicationWithTypeWithExtras(sr.app.uid, sr.app.getPid(),
3985	                            sr.app.info.packageName, sr.app.userId, reason, false /*force*/,
3986	                            ForegroundServiceDidNotStopInTimeException.TYPE_ID,
3987	                            ForegroundServiceDidNotStopInTimeException
3988	                                    .createExtrasForService(sr.getComponentName()));
3989	                }
3990	            } else {
3991	                // Log a WTF instead of crashing the app while the new behavior is gated.
3992	                Slog.wtf(TAG, reason);
3993	            }
3994	        }
3995	    }
