4035	    private boolean updateServiceClientActivitiesLocked(ProcessServiceRecord psr,
4036	            ConnectionRecord modCr, boolean updateLru) {
4037	        if (modCr != null && modCr.binding.client != null) {
4038	            if (!modCr.binding.client.hasActivities()) {
4039	                // This connection is from a client without activities, so adding
4040	                // and removing is not interesting.
4041	                return false;
4042	            }
4043	        }
4044	
4045	        boolean anyClientActivities = false;
4046	        for (int i = psr.numberOfRunningServices() - 1; i >= 0 && !anyClientActivities; i--) {
4047	            ServiceRecord sr = psr.getRunningServiceAt(i);
4048	            ArrayMap<IBinder, ArrayList<ConnectionRecord>> connections = sr.getConnections();
4049	            for (int conni = connections.size() - 1; conni >= 0 && !anyClientActivities; conni--) {
4050	                ArrayList<ConnectionRecord> clist = connections.valueAt(conni);
4051	                for (int cri=clist.size()-1; cri>=0; cri--) {
4052	                    ConnectionRecord cr = clist.get(cri);
4053	                    if (cr.binding.client == null || cr.binding.client == psr.mApp) {
4054	                        // Binding to ourself is not interesting.
4055	                        continue;
4056	                    }
4057	                    if (cr.binding.client.hasActivities()) {
4058	                        anyClientActivities = true;
4059	                        break;
4060	                    }
4061	                }
4062	            }
4063	        }
4064	        if (anyClientActivities != psr.hasClientActivities()) {
4065	            mAm.mProcessStateController.setHasClientActivities(psr, anyClientActivities);
4066	            if (updateLru) {
4067	                mAm.updateLruProcessLocked(psr.mApp, anyClientActivities, null);
4068	            }
4069	            return true;
4070	        }
4071	        return false;
4072	    }
